"use client"

// Ported from Uiverse galaxy（MIT，(c) 2023 Uiverse.io, author codebykay101）— https://github.com/uiverse-io/galaxy/blob/main/Cards/codebykay101_red-fox-31.html. Modified for effect-ui.

import { useRef, type CSSProperties, type HTMLAttributes } from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

const CSS = `
[data-slot="glow-wander-card"] [data-cell] {
  position: relative;
  width: 150px;
  height: 150px;
  overflow: hidden;
  background: color-mix(in oklab, var(--foreground) 88%, black);
  transform: rotate(calc(90deg * var(--i)));
}
[data-slot="glow-wander-card"] [data-cell]::before {
  content: "";
  position: absolute;
  width: 300px;
  height: 300px;
  background: radial-gradient(var(--clr), transparent);
  animation: glow-wander-card-move var(--glow-duration) linear infinite;
}
[data-slot="glow-wander-card"][data-motion="off"] [data-cell]::before {
  animation: none;
  transform: translate(-40px, -40px);
}
[data-slot="glow-wander-card"] [data-cell]::after {
  content: "";
  position: absolute;
  inset: 2px;
  background: color-mix(in oklab, var(--foreground) 82%, black);
}
@keyframes glow-wander-card-move {
  0% { transform: translate(-150px, -150px); }
  25% { transform: translate(0, -150px); }
  50% { transform: translate(0, 0); }
  75% { transform: translate(-150px, 0); }
  100% { transform: translate(-150px, -150px); }
}
`

export interface GlowWanderCardProps extends HTMLAttributes<HTMLDivElement> {
  /** 每块的发光色。不传时使用图表色。 */
  colors?: string[]
  /** 光点绕一圈的秒数。 */
  duration?: number
}

export function GlowWanderCard({ colors, duration = 1.5, className, style, ...props }: GlowWanderCardProps) {
  const ref = useRef<HTMLDivElement>(null)
  const reduced = usePrefersReducedMotion()
  const motionOn = useAnimationActive(ref)
  const palette = [colors?.[0] ?? "var(--chart-1)", colors?.[1] ?? "var(--chart-2)", colors?.[2] ?? "var(--chart-3)"]
  const painted = { "--glow-duration": `${duration}s`, ...style } as CSSProperties

  return (
    <div
      {...props}
      ref={ref}
      className={cn("flex items-center justify-center gap-5", className)}
      data-motion={motionOn && !reduced ? "on" : "off"}
      data-reduced={reduced ? "true" : "false"}
      data-slot="glow-wander-card"
      style={painted}
    >
      <style>{CSS}</style>
      {palette.map((color, index) => (
        <div
          key={color + index}
          data-cell=""
          style={{ "--clr": color, "--i": String(index + 1) } as CSSProperties}
        />
      ))}
    </div>
  )
}

import type { ReactNode } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

const EDGE = "#7c3aed"

export interface GlowingEdgeProps {
  children: ReactNode
  className?: string
  /** 旋转一周的时长，毫秒。不传或 6000 仍是 6 秒。 */
  duration?: number
  /** 描边颜色。不传或 #7c3aed 仍用原来的紫色渐变。 */
  color?: string
  /** 色带张角倍率。不传或 1 仍是 70° 到 140°。 */
  intensity?: number
  /** 描边厚度，像素。不传或 1 仍是 1px。 */
  size?: number
}

function GlowingEdge({ children, className, duration, color, intensity, size }: GlowingEdgeProps) {
  const reduced = usePrefersReducedMotion()
  const timed = duration === undefined || duration === 6000
  const painted = color === undefined || color.toLowerCase() === EDGE
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const width = size === undefined || size === 1 ? 1 : size
  const canonical = timed && painted && gain === 1
  return (
    <div className={cn("relative overflow-hidden rounded-2xl", width === 1 && "p-px", className)} style={width === 1 ? undefined : { padding: width }}>
      <div
        aria-hidden
        className={cn(
          "absolute inset-[-40%] motion-reduce:animate-none",
          canonical &&
            "animate-[glow-orbit_6s_linear_infinite] bg-[conic-gradient(from_var(--shine-angle),transparent_0deg,#7c3aed_70deg,transparent_140deg)]",
        )}
        style={
          canonical
            ? undefined
            : {
                animation: reduced ? "none" : timed ? "glow-orbit 6s linear infinite" : `glow-orbit ${duration}ms linear infinite`,
                background: `conic-gradient(from var(--shine-angle), transparent 0deg, ${painted ? EDGE : color} ${70 * gain}deg, transparent ${140 * gain}deg)`,
              }
        }
      />
      <div className="relative rounded-[calc(var(--radius)+2px)] bg-card p-5">{children}</div>
    </div>
  )
}

export { GlowingEdge }

