"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { cn } from "@/lib/utils"

export interface GpgpuParticlesProps {
  className?: string
  count?: number
  text?: string
  speed?: number
  size?: number
}

const SIM = `
precision highp float;
uniform sampler2D tMap;
uniform vec2 uMouse;
uniform float uTime;
uniform float uForm;
varying vec2 vUv;

void main() {
  vec4 data = texture2D(tMap, vUv);
  vec2 pos = data.xy;
  vec2 target = data.zw;
  vec2 toMouse = pos - uMouse;
  float dist = length(toMouse) + 0.0001;
  vec2 tangent = vec2(-toMouse.y, toMouse.x) / dist;
  pos += tangent * 0.012 / dist;
  pos += (target - pos) * 0.045 * uForm;
  pos += vec2(sin(uTime + pos.y * 8.0), cos(uTime + pos.x * 8.0)) * 0.0012;
  pos = clamp(pos, vec2(-1.15), vec2(1.15));
  gl_FragColor = vec4(pos, target);
}
`

const VERT = `
attribute vec2 uv;
attribute vec2 position;
uniform sampler2D tMap;
uniform float uSize;
varying float vAlpha;
void main() {
  vec4 data = texture2D(tMap, uv);
  vAlpha = 0.75;
  gl_Position = vec4(data.xy, 0.0, 1.0);
  gl_PointSize = uSize;
}
`

const FRAG = `
precision highp float;
varying float vAlpha;
void main() {
  vec2 p = gl_PointCoord * 2.0 - 1.0;
  float d = 1.0 - clamp(dot(p, p), 0.0, 1.0);
  gl_FragColor = vec4(0.55, 0.82, 1.0, d * vAlpha);
}
`

function textTargets(text: string, count: number) {
  const canvas = document.createElement("canvas")
  canvas.width = 256
  canvas.height = 128
  const ctx = canvas.getContext("2d")
  if (!ctx) return []
  ctx.fillStyle = "#000"
  ctx.fillRect(0, 0, 256, 128)
  ctx.fillStyle = "#fff"
  ctx.font = "bold 52px ui-sans-serif"
  ctx.textAlign = "center"
  ctx.textBaseline = "middle"
  ctx.fillText(text, 128, 64)
  const pixels = ctx.getImageData(0, 0, 256, 128).data
  const hits: [number, number][] = []
  for (let y = 0; y < 128; y += 2) {
    for (let x = 0; x < 256; x += 2) {
      if ((pixels[(y * 256 + x) * 4 + 3] ?? 0) > 80) {
        hits.push([(x / 256) * 2 - 1, 1 - (y / 128) * 2])
      }
    }
  }
  return Array.from({ length: count }, (_, index) => hits[index % Math.max(hits.length, 1)] ?? [0, 0])
}

function useReducedMotion() {
  return React.useSyncExternalStore(
    (onChange) => {
      const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
      mq.addEventListener("change", onChange)
      return () => mq.removeEventListener("change", onChange)
    },
    () => window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    () => false,
  )
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function GpgpuParticles({
  className,
  count = 1400,
  text = "effect-ui",
  speed = 1,
  size = 2.4,
}: GpgpuParticlesProps) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(hostRef)
  const reduced = useReducedMotion()
  const [fallback, setFallback] = React.useState(false)
  const mouse = React.useRef({ x: 0, y: 0 })
  const speedRef = React.useRef(playbackRate(speed))
  const sizeRef = React.useRef(size)

  React.useEffect(() => {
    speedRef.current = playbackRate(speed)
    sizeRef.current = size
  }, [speed, size])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || reduced || !active) return

    let cancelled = false
    let frame = 0

    const run = async () => {
      const ogl = await import("ogl")
      if (!canvas || cancelled) return
      const renderer = new ogl.Renderer({ canvas, alpha: true, dpr: Math.min(window.devicePixelRatio || 1, 2) })
      const gl = renderer.gl
      const targets = textTargets(text, count)
      const data = new Float32Array(count * 4)
      for (let i = 0; i < count; i += 1) {
        data[i * 4] = Math.random() * 2 - 1
        data[i * 4 + 1] = Math.random() * 2 - 1
        data[i * 4 + 2] = targets[i]?.[0] ?? 0
        data[i * 4 + 3] = targets[i]?.[1] ?? 0
      }
      const gpgpu = new ogl.GPGPU(gl, { data })
      gpgpu.addPass({
        fragment: SIM,
        uniforms: {
          uMouse: { value: new ogl.Vec2() },
          uTime: { value: 0 },
          uForm: { value: 0 },
        },
      })
      const geometry = new ogl.Geometry(gl, {
        position: { size: 2, data: new Float32Array(count * 2) },
        uv: { size: 2, data: gpgpu.coords },
      })
      const pointUniforms = {
        tMap: gpgpu.uniform,
        uSize: { value: 2.4 },
      }
      const program = new ogl.Program(gl, {
        vertex: VERT,
        fragment: FRAG,
        uniforms: pointUniforms,
        transparent: true,
        depthTest: false,
      })
      const particles = new ogl.Mesh(gl, { geometry, program, mode: gl.POINTS })

      const resize = () => {
        const { width, height } = canvas.getBoundingClientRect()
        renderer.setSize(width, height)
      }
      resize()

      let time = 0
      const tick = () => {
        time += 0.016 * speedRef.current
        pointUniforms.uSize.value = sizeRef.current
        const pass = gpgpu.passes[0]
        if (pass) {
          pass.uniforms.uTime.value = time
          pass.uniforms.uMouse.value.set(mouse.current.x, mouse.current.y)
          pass.uniforms.uForm.value = 0.15 + 0.85 * (0.5 + 0.5 * Math.sin(time * 0.35))
        }
        gpgpu.render()
        renderer.render({ scene: particles })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      window.addEventListener("resize", resize)
      return () => {
        window.cancelAnimationFrame(frame)
        window.removeEventListener("resize", resize)
      }
    }

    const cleanup = run().catch(() => {
      if (!cancelled) queueMicrotask(() => setFallback(true))
    })
    return () => {
      cancelled = true
      void cleanup.then((fn) => fn?.())
    }
  }, [active, count, reduced, text])

  return (
    <div
      ref={hostRef}
      className={cn("relative min-h-56 overflow-hidden rounded-xl border bg-zinc-950", className)}
      onPointerMove={(event) => {
        const rect = event.currentTarget.getBoundingClientRect()
        mouse.current.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
        mouse.current.y = -(((event.clientY - rect.top) / rect.height) * 2 - 1)
      }}
    >
      {fallback || reduced ? (
        <div className="grid h-full min-h-56 place-items-center font-mono text-2xl tracking-[0.4em] text-cyan-200">
          {text}
        </div>
      ) : (
        <canvas ref={canvasRef} className="absolute inset-0 size-full" />
      )}
    </div>
  )
}

export { GpgpuParticles }

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface GradientCard {
  title: string
  detail: string
}

export interface GradientCarousel3dProps {
  items?: GradientCard[]
  className?: string
  /** 拖拽灵敏度倍率。不传或 1 时仍除以 180。 */
  speed?: number
  /** 侧向转角。不传或 42 仍是 42°。 */
  angle?: number
  /** 卡片缩放倍率。不传或 1 时中心仍是 1.18。 */
  scale?: number
  /** 色相跟随倍率。不传或 1 时仍是位移乘 8。 */
  intensity?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

const DEFAULTS: GradientCard[] = [
  { title: "晨光", detail: "从暖色走到冷色" },
  { title: "海岸", detail: "中心的卡片会放大" },
  { title: "林地", detail: "松手后还带着惯性" },
  { title: "夜市", detail: "渐变跟着位置走" },
  { title: "雪线", detail: "沿弧线一直排下去" },
  { title: "剧场", detail: "拖拽可以绕回来" },
]

function mod(value: number, length: number) {
  return ((value % length) + length) % length
}

function GradientCarousel3d({ items = DEFAULTS, className, speed, angle, scale, intensity }: GradientCarousel3dProps) {
  const rate = pace(speed)
  const turn = angle === undefined || angle === 42 ? 42 : angle
  const gain = scale === undefined || scale === 1 ? 1 : scale
  const hueGain = intensity === undefined || intensity === 1 ? 1 : intensity
  const divisor = rate === 1 ? 180 : 180 / rate
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const offsetRef = React.useRef(0)
  const velocityRef = React.useRef(0)
  const visibleRef = React.useRef(true)
  const dragRef = React.useRef<{ x: number; offset: number; last: number } | null>(null)
  const [offset, setOffset] = React.useState(0)
  const frameRef = React.useRef(0)

  React.useEffect(() => {
    const host = hostRef.current
    if (!host || reduced) return
    const observer = new IntersectionObserver((entries) => {
      visibleRef.current = entries.some((entry) => entry.isIntersecting)
      if (!visibleRef.current) {
        window.cancelAnimationFrame(frameRef.current)
        frameRef.current = 0
      }
    })
    observer.observe(host)
    return () => {
      observer.disconnect()
      window.cancelAnimationFrame(frameRef.current)
    }
  }, [reduced])

  const settle = React.useCallback(() => {
    if (frameRef.current || reduced) return
    const tick = () => {
      if (!visibleRef.current) {
        frameRef.current = 0
        return
      }
      offsetRef.current += velocityRef.current
      velocityRef.current *= 0.94
      setOffset(offsetRef.current)
      if (Math.abs(velocityRef.current) > 0.0012) frameRef.current = window.requestAnimationFrame(tick)
      else frameRef.current = 0
    }
    frameRef.current = window.requestAnimationFrame(tick)
  }, [reduced])

  if (reduced) {
    return (
      <div data-slot="gradient-carousel-3d" className={cn("flex gap-3 overflow-x-auto snap-x snap-mandatory px-4 py-6", className)}>
        {items.map((item, index) => (
          <article key={item.title} className="w-56 shrink-0 snap-center rounded-2xl p-4 text-slate-950" style={{ backgroundImage: `linear-gradient(145deg, hsl(${index * 48} 80% 68%), hsl(${index * 48 + 40} 70% 42%))` }}>
            <h3 className="text-lg font-medium">{item.title}</h3>
            <p className="mt-2 text-sm">{item.detail}</p>
          </article>
        ))}
      </div>
    )
  }

  const length = Math.max(items.length, 1)
  const base = Math.round(offset)
  const slots = [-2, -1, 0, 1, 2]

  return (
    <div
      data-slot="gradient-carousel-3d"
      className={cn("relative h-96 overflow-hidden rounded-xl border bg-slate-950", className)}
    >
    <div
      ref={hostRef}
      className="absolute inset-0 [perspective:1200px]"
      onPointerDown={(event) => {
        dragRef.current = { x: event.clientX, offset: offsetRef.current, last: event.clientX }
        velocityRef.current = 0
        window.cancelAnimationFrame(frameRef.current)
        frameRef.current = 0
        event.currentTarget.setPointerCapture(event.pointerId)
      }}
      onPointerMove={(event) => {
        const drag = dragRef.current
        if (!drag) return
        const next = drag.offset - (event.clientX - drag.x) / divisor
        velocityRef.current = (drag.last - event.clientX) / divisor
        drag.last = event.clientX
        offsetRef.current = next
        setOffset(next)
      }}
      onPointerUp={() => {
        dragRef.current = null
        settle()
      }}
    >
      <div className="absolute inset-0 [transform-style:preserve-3d]">
        {slots.map((slot) => {
          const index = mod(base + slot, length)
          const item = items[index]
          if (!item) return null
          const delta = base + slot - offset
          const cardScale = (1.18 - Math.min(Math.abs(delta), 3) * 0.12) * (gain === 1 ? 1 : gain)
          const hue = (index * 46 + offset * (hueGain === 1 ? 8 : 8 * hueGain)) % 360
          return (
            <article
              key={`${item.title}-${slot}`}
              className="absolute top-1/2 left-1/2 h-44 w-56 rounded-2xl p-4 text-slate-950 shadow-xl"
              style={{
                transform: `translate(-50%, -50%) rotateY(${delta * -turn}deg) translateZ(280px) scale(${cardScale})`,
                backgroundImage: `linear-gradient(160deg, hsl(${hue} 86% 70%), hsl(${(hue + 36) % 360} 72% 42%))`,
              }}
            >
              <h3 className="text-xl font-medium">{item.title}</h3>
              <p className="mt-2 text-sm">{item.detail}</p>
            </article>
          )
        })}
      </div>
      <p className="pointer-events-none absolute bottom-3 left-3 text-xs text-white/70">左右拖拽，松手后会滑一段。</p>
    </div>
    </div>
  )
}

