const DEFAULTS = [
  ["晨窗", "#fb7185"],
  ["长廊", "#38bdf8"],
  ["书架", "#f59e0b"],
  ["港口", "#34d399"],
  ["夜市", "#818cf8"],
  ["雪线", "#e2e8f0"],
