function paintCard(label: string, color: string) {
  const canvas = document.createElement("canvas")
  canvas.width = 512
  canvas.height = 320
  const context = canvas.getContext("2d")
  if (!context) return canvas
  context.fillStyle = color
  context.fillRect(0, 0, 512, 320)
  context.fillStyle = "rgba(15,23,42,0.28)"
  context.fillRect(0, 220, 512, 100)
  context.fillStyle = "#0f172a"
  context.font = "64px sans-serif"
  context.fillText(label, 36, 120)
  return canvas
}

function ImageTubeScroll({ images, radius = 1.35, speed = 1, intensity, className }: ImageTubeScrollProps) {
  const reduced = usePrefersReducedMotion()
  const sectionRef = React.useRef<HTMLElement>(null)
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(hostRef)
  const activeRef = React.useRef(false)
  const kickRef = React.useRef<(() => void) | null>(null)
  const progressRef = React.useRef(0)
  const speedRef = React.useRef(speed)
  const radiusRef = React.useRef(radius)
  const intensityRef = React.useRef(intensity)
  const dragRef = React.useRef<{ x: number; speed: number } | null>(null)
  const [fallback, setFallback] = React.useState(false)
  const [dragSpeed, setDragSpeed] = React.useState<number | null>(null)
  const shownSpeed = dragSpeed ?? speed
  const { scrollYProgress } = useScroll({ target: sectionRef, offset: ["start start", "end end"] })
  const cards = images?.length ? images : DEFAULTS.map(([label]) => label)
  const showCanvas = !reduced && !fallback

  useMotionValueEvent(scrollYProgress, "change", (value) => {
    progressRef.current = value
  })

  React.useEffect(() => {
    speedRef.current = shownSpeed
  }, [shownSpeed])

  React.useEffect(() => {
    radiusRef.current = radius
  }, [radius])

  React.useEffect(() => {
    intensityRef.current = intensity
  }, [intensity])

  React.useEffect(() => {
    activeRef.current = active
    if (active) kickRef.current?.()
  }, [active])

  React.useEffect(() => {
    if (!showCanvas) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: false, dpr: Math.min(window.devicePixelRatio || 1, 1.5) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 55, near: 0.1, far: 40 })
      const scene = new ogl.Transform()
      const tube = new ogl.Transform()
      tube.setParent(scene)
      const around = 4
      const records: { mesh: InstanceType<typeof ogl.Mesh>; angle: number; layer: number }[] = []
      const sources = images?.length ? images : DEFAULTS.map(([label, color]) => ({ label, color }))
      const rings = Math.max(6, Math.ceil(sources.length / around))
      for (let index = 0; index < rings * around; index += 1) {
        const source = sources[index % sources.length]
        if (!source) continue
        const label = typeof source === "string" ? `画面 ${(index % sources.length) + 1}` : source.label
        const color = typeof source === "string" ? "#334155" : source.color
        const image = typeof source === "string" ? undefined : paintCard(label, color)
        const texture = new ogl.Texture(gl, {
          image: image ?? undefined,
          minFilter: gl.LINEAR,
          magFilter: gl.LINEAR,
          wrapS: gl.CLAMP_TO_EDGE,
          wrapT: gl.CLAMP_TO_EDGE,
        })
        if (typeof source === "string") {
          const picture = new Image()
          picture.onload = () => {
            texture.image = picture
            texture.needsUpdate = true
          }
          picture.src = source
        }
        const geometry = new ogl.Plane(gl, { width: 1.45, height: 0.92 })
        const program = new ogl.Program(gl, {
          vertex: `
            attribute vec2 uv;
            attribute vec3 position;
            uniform mat4 modelViewMatrix;
            uniform mat4 projectionMatrix;
            varying vec2 vUv;
            void main() {
              vUv = uv;
              gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
          `,
          fragment: `
            precision highp float;
            uniform sampler2D u_map;
            varying vec2 vUv;
            void main() {
              gl_FragColor = texture2D(u_map, vUv);
            }
          `,
          uniforms: { u_map: { value: texture } },
          cullFace: false,
        })
        const mesh = new ogl.Mesh(gl, { geometry, program, frustumCulled: false })
        mesh.setParent(tube)
        records.push({ mesh, angle: (index % around) * ((Math.PI * 2) / around), layer: Math.floor(index / around) })
      }
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect: Math.max(rect.width, 1) / Math.max(rect.height, 1) })
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const tick = () => {
        if (!activeRef.current) {
          frame = 0
          return
        }
        const progress = progressRef.current
        const currentRadius = radiusRef.current
        const spacing = 2.35
        const travel = Math.max(rings - 1, 1) * spacing
        const paced = Math.min(1, progress * Math.max(speedRef.current, 0.35))
        const tilt = intensityRef.current === undefined || intensityRef.current === 1 ? 0.55 : 0.55 * intensityRef.current
        tube.rotation.z = progress * Math.PI * 2 * speedRef.current
        camera.position.z = 1.7 - paced * travel
        for (const record of records) {
          const z = -record.layer * spacing
          record.mesh.position.set(Math.sin(record.angle) * currentRadius, Math.cos(record.angle) * currentRadius, z)
          record.mesh.rotation.x = -Math.cos(record.angle) * tilt
          record.mesh.rotation.y = Math.sin(record.angle) * tilt
          record.mesh.rotation.z = 0
        }
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      kickRef.current = () => {
        if (activeRef.current && frame === 0) frame = window.requestAnimationFrame(tick)
      }
      kickRef.current()
      return () => {
        kickRef.current = null
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) queueMicrotask(() => { if (!cancelled) setFallback(true) })
      return undefined
    })
    return () => {
      cancelled = true
      kickRef.current = null
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [images, showCanvas])

  return (
    <section ref={sectionRef} data-slot="image-tube-scroll" className={cn(showCanvas ? "relative h-[220vh]" : "relative", className)}>
      <div className={cn(showCanvas && "sticky top-0 h-svh")}>
        <p className="px-4 pt-4 text-xs text-muted-foreground">滚动穿过图片管道。左右拖动可以改变速度，当前 {shownSpeed.toFixed(2)}。</p>
        {showCanvas ? (
          <div
            ref={hostRef}
            className="relative h-[calc(100svh-4rem)] touch-none"
            onPointerDown={(event) => {
              dragRef.current = { x: event.clientX, speed: speedRef.current }
              event.currentTarget.setPointerCapture(event.pointerId)
            }}
            onPointerMove={(event) => {
              if (!dragRef.current) return
              const next = Math.min(2.4, Math.max(0.25, dragRef.current.speed + (event.clientX - dragRef.current.x) * 0.004))
              setDragSpeed(next)
            }}
            onPointerUp={() => {
              dragRef.current = null
            }}
          >
            <canvas ref={canvasRef} className="absolute inset-0 size-full" />
          </div>
        ) : (
          <ul className="grid gap-3 p-4">
            {cards.map((card) => (
              <li key={card} className="rounded-xl border bg-muted px-4 py-8 text-lg">
                {card}
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  )
}

export { ImageTubeScroll }

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface CanvasTile {
  label: string
  tint: string
}

export interface InfiniteCanvasGalleryProps {
  tiles?: CanvasTile[]
  className?: string
  gap?: number
  size?: number
}

const defaultTiles: CanvasTile[] = [
  { label: "01", tint: "#312e81" },
  { label: "02", tint: "#7c3aed" },
  { label: "03", tint: "#22d3ee" },
  { label: "04", tint: "#f472b6" },
  { label: "05", tint: "#f59e0b" },
  { label: "06", tint: "#0f766e" },
]

const STEP = 168

function InfiniteCanvasGallery({ tiles = defaultTiles, className, gap, size }: InfiniteCanvasGalleryProps) {
  const reduced = usePrefersReducedMotion()
  const frameRef = React.useRef<HTMLDivElement>(null)
  const offsetRef = React.useRef({ x: 24, y: 16 })
  const velocity = React.useRef({ x: 0, y: 0 })
  const drag = React.useRef<{ x: number; y: number; ox: number; oy: number; lx: number; ly: number } | null>(null)
  const [offset, setOffset] = React.useState({ x: 24, y: 16 })
  const [viewport, setViewport] = React.useState({ w: 640, h: 360 })
  const step = gap === undefined || gap === STEP ? STEP : gap
  const tileCanonical = size === undefined || size === 160

  React.useEffect(() => {
    const element = frameRef.current
    if (!element) return
    const update = () => setViewport({ w: element.clientWidth, h: element.clientHeight })
    update()
    const observer = new ResizeObserver(update)
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  const publish = () => setOffset({ x: offsetRef.current.x, y: offsetRef.current.y })

  const coast = () => {
    if (reduced || drag.current) return
    const step = () => {
      if (drag.current) return
      if (Math.abs(velocity.current.x) < 0.2 && Math.abs(velocity.current.y) < 0.2) return
      offsetRef.current = {
        x: offsetRef.current.x + velocity.current.x,
        y: offsetRef.current.y + velocity.current.y,
      }
      velocity.current.x *= 0.94
      velocity.current.y *= 0.94
      publish()
      window.requestAnimationFrame(step)
    }
    window.requestAnimationFrame(step)
  }

  const col0 = Math.floor(-offset.x / step) - 1
  const row0 = Math.floor(-offset.y / step) - 1
  const cols = Math.ceil(viewport.w / step) + 3
  const rows = Math.ceil(viewport.h / step) + 3
  const cells: { col: number; row: number }[] = []
  for (let row = row0; row < row0 + rows; row += 1) {
    for (let col = col0; col < col0 + cols; col += 1) cells.push({ col, row })
  }

  return (
    <div
      ref={frameRef}
      className={cn("relative h-80 cursor-grab overflow-hidden rounded-2xl border bg-zinc-950 active:cursor-grabbing", className)}
      style={{ touchAction: "none" }}
      onPointerDown={(event) => {
        drag.current = {
          x: event.clientX,
          y: event.clientY,
          ox: offsetRef.current.x,
          oy: offsetRef.current.y,
          lx: event.clientX,
          ly: event.clientY,
        }
        event.currentTarget.setPointerCapture(event.pointerId)
      }}
      onPointerMove={(event) => {
        const current = drag.current
        if (!current) return
        const next = {
          x: current.ox + event.clientX - current.x,
          y: current.oy + event.clientY - current.y,
        }
        velocity.current = { x: event.clientX - current.lx, y: event.clientY - current.ly }
        current.lx = event.clientX
        current.ly = event.clientY
        offsetRef.current = next
        publish()
      }}
      onPointerUp={() => {
        drag.current = null
        coast()
      }}
    >
      {cells.map(({ col, row }) => {
        const tile = tiles[Math.abs((col * 3 + row * 5) % tiles.length)] ?? tiles[0]
        if (!tile) return null
        return (
          <div
            key={`${col}:${row}`}
            className={
              tileCanonical
                ? "absolute grid size-40 place-items-end rounded-xl p-3 text-sm text-white"
                : "absolute grid place-items-end rounded-xl p-3 text-sm text-white"
            }
            style={{
              transform: `translate(${col * step + offset.x}px, ${row * step + offset.y}px)`,
              background: `linear-gradient(160deg, ${tile.tint}, #09090b)`,
              ...(tileCanonical || size === undefined ? {} : { width: size, height: size }),
            }}
          >
            {tile.label}
          </div>
        )
      })}
    </div>
  )
}

