    if (next && root.current?.contains(next)) return;
    if (!next && !document.hasFocus()) return;
    submit("blur");
  }

  const noun = label.toLowerCase();
  const message = error
    ? { key: `error:${error}`, tone: "error" as const, node: <><CircleAlert className={styles.messageIcon} size={14} strokeWidth={2} aria-hidden="true" /><span>{error}</span></> }
    : failed && !editing
      ? { key: `failed:${failed}`, tone: "failed" as const, node: <><CircleAlert className={styles.messageIcon} size={14} strokeWidth={2} aria-hidden="true" /><span>{`Couldn’t save “${failed}”, so the last saved ${noun} is back.`} <button type="button" className={styles.retry} onClick={retry}>Try again</button></span></> }
      : null;
  const slot = editing ? "edit" : phase;
  const describedBy = (hint: string) => [hint, message ? messageId : null].filter(Boolean).join(" ");
  const fieldProps = {
    className: styles.control, value: draft, onChange, onKeyDown, placeholder, "aria-label": label, "aria-invalid": error ? true : undefined,
    "aria-describedby": describedBy(editHintId), autoComplete: "off", spellCheck: variant === "body",
  };

  return <ArcQuiet.Provider value={!arcLive}><ArcStyle /><div data-slot="inline-edit" data-reduced={preferReduced ? "true" : "false"} data-motion={arcLive && !preferReduced ? "on" : "off"}  ref={root} className={[styles.root, className].filter(Boolean).join(" ")} data-variant={variant} data-multiline={multiline || undefined} data-editing={editing || undefined}
    data-phase={phase} data-invalid={error ? "" : undefined} data-flash={flash ?? undefined} onBlur={onBlur}>
    <Tag className={styles.line}>
      <motion.span ref={box} className={styles.box} style={multiline ? { height: boxHeight } : undefined}>
        {/* The text stays in flow while editing, hidden and mirroring the draft, so it sizes the box and can roll back with motion on Escape. */}
        <button ref={display} type="button" className={styles.display} onClick={onDisplayClick} tabIndex={editing ? -1 : undefined}
          aria-label={`${label}: ${shown || placeholder}`} aria-describedby={describedBy(displayHintId)} aria-disabled={saving || undefined}>
          <span className={styles.layer} data-empty={layerText ? undefined : ""}>
            <AnimatePresence mode="popLayout" initial={false} custom={layer.direction}>
              <motion.span key={layer.key} data-layer={layer.key} className={styles.text} custom={layer.direction} variants={reduced ? textFade : textMotion} initial="enter" animate="rest" exit="exit">
                {/* A zero-width space keeps the line box, so an empty field never collapses. */}
                {(layerText || placeholder || "​") + (multiline && editing ? "​" : "")}
              </motion.span>
            </AnimatePresence>
          </span>
        </button>
        {editing && (multiline
          ? <textarea ref={node => { control.current = node; }} {...fieldProps} rows={1} enterKeyHint="done" />
          : <input ref={node => { control.current = node; }} {...fieldProps} type="text" enterKeyHint="done" />)}
        <motion.span ref={frame} className={styles.frame} style={multiline ? undefined : { width: frameWidth }}>
          <span className={styles.slot}>
            <AnimatePresence initial={false}>
              <motion.span key={slot} className={styles.slotItem} initial={reduced ? fadeIn : iconIn} animate={rest} exit={reduced ? fadeOut : iconOut} transition={reduced ? { duration: motionTokens.duration.fast } : iconEnter}>
                {slot === "edit" ? <span className={styles.actions}>
                  <button type="button" className={styles.save} aria-label={`Save ${noun}`} onPointerDown={event => event.preventDefault()} onClick={() => submit("button")}><Check size={15} strokeWidth={2} aria-hidden="true" /></button>
                  <button type="button" className={styles.cancel} aria-label="Cancel editing" onPointerDown={event => event.preventDefault()} onClick={cancel}><X size={15} strokeWidth={2} aria-hidden="true" /></button>
                </span>
                  : slot === "saving" ? <span className={styles.spinner} aria-hidden="true" />
                  : slot === "saved" ? <span className={styles.saved} aria-hidden="true"><DrawnCheck reduced={reduced} /></span>
                  : slot === "failed" ? <CircleAlert className={styles.failedIcon} size={16} strokeWidth={1.75} aria-hidden="true" />
                  : <Pencil className={styles.pencil} size={14} strokeWidth={1.75} aria-hidden="true" onClick={() => startEdit(shown.length)} />}
              </motion.span>
            </AnimatePresence>
          </span>
        </motion.span>
      </motion.span>
    </Tag>
    <Reveal id={messageId} message={message} reduced={reduced} />
    <span id={displayHintId} className={styles.srOnly}>Activate to edit.</span>
    <span id={editHintId} className={styles.srOnly}>{multiline ? "Enter saves, Shift+Enter adds a line break, Escape cancels." : "Enter saves, Escape cancels."}</span>
    <span className={styles.srOnly} role="status">{announcement}</span>
  </div></ArcQuiet.Provider>;
}

export default InlineEdit;

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/inline-testimonials/index.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"


const HOVER_QUERY = "(hover: hover) and (pointer: fine)";

function subscribeHover(onStoreChange: () => void) {
  const media = window.matchMedia(HOVER_QUERY);
  media.addEventListener("change", onStoreChange);
  return () => media.removeEventListener("change", onStoreChange);
}

function hoverSnapshot() {
  return window.matchMedia(HOVER_QUERY).matches;
}

function useHoverCapable() {
  return useSyncExternalStore(subscribeHover, hoverSnapshot, () => false);
}

import { Star } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import type { FocusEvent } from "react";
import { Fragment, useCallback, useEffect, useRef, useState, useSyncExternalStore } from "react";

const TOKEN_PATTERN = /\{\{([\w-]+)\}\}/g;
const DEFAULT_AVATAR_SIZE = 22;
const CARD_AVATAR_MULTIPLIER = 2;
const CARD_WIDTH_PX = 288;
const EDGE_PADDING_PX = 8;
const CARD_GAP_PX = 8;
const ENTER_OFFSET_PX = 4;
const CLOSE_DELAY_MS = 140;
const STAR_COUNT = 5;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;
const SPRING = { bounce: 0.1, duration: 0.25, type: "spring" } as const;
/** Leaving is a decision already made — get out of the way faster. */
const EXIT_TRANSITION = { duration: 0.15, ease: EASE_OUT } as const;
const INSTANT = { duration: 0 } as const;

type TextSegment =
  | { type: "text"; value: string }
  | { type: "token"; id: string };

type CardPosition = {
  left: number;
  originX: number;
  spaceAbove: number;
  spaceBelow: number;
  triggerBottom: number;
  triggerTop: number;
  width: number;
};

const parseSegments = (text: string): TextSegment[] => {
  const segments: TextSegment[] = [];
  let lastIndex = 0;

  for (const match of text.matchAll(TOKEN_PATTERN)) {
    const full = match[0];
    const id = match[1];
    const index = match.index ?? 0;
    if (!id) {
      continue;
    }
    if (index > lastIndex) {
      segments.push({ type: "text", value: text.slice(lastIndex, index) });
    }
    segments.push({ id, type: "token" });
    lastIndex = index + full.length;
  }

  if (lastIndex < text.length) {
    segments.push({ type: "text", value: text.slice(lastIndex) });
  }

  return segments;
};

export type Testimonial = {
  avatar: string;
  id: string;
  name: string;
  quote: string;
  rating?: number;
  role: string;
};

export type InlineTestimonialsProps = {
  avatarSize?: number;
  className?: string;
  onOpenChange?: (id: string | null) => void;
  openId?: string | null;
  testimonials: Testimonial[];
  text: string;
};

const QuoteCard = ({
  avatarSize,
  cardId,
  testimonial,
}: {
  avatarSize: number;
  cardId: string;
  testimonial: Testimonial;
}) => (
  <div
    className={cn(
      "rounded-xl border border-foreground/10 bg-background p-4 text-left",
      // Ambient + direct light rather than one flat drop, so the card reads as
      // lifted off the paragraph instead of stamped onto it.
      "shadow-[0_1px_2px_rgb(0_0_0/0.05),0_14px_32px_-14px_rgb(0_0_0/0.28)]",
      "dark:border-foreground/15 dark:bg-smooth-100 dark:shadow-[0_1px_2px_rgb(0_0_0/0.4),0_14px_32px_-14px_rgb(0_0_0/0.7)]"
    )}
    id={cardId}
  >
    <div className="flex items-center gap-3">
      {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
        alt=""
        className="shrink-0 rounded-full object-cover"
        height={avatarSize * CARD_AVATAR_MULTIPLIER}
        src={testimonial.avatar}
        width={avatarSize * CARD_AVATAR_MULTIPLIER}
      />
      <div className="min-w-0">
        <p className="truncate font-semibold text-foreground text-sm">
          {testimonial.name}
        </p>
        <p className="truncate text-muted-foreground text-xs">
          {testimonial.role}
        </p>
      </div>
    </div>
    <blockquote className="mt-3 text-foreground/80 text-sm leading-relaxed">
      {testimonial.quote}
    </blockquote>
    {testimonial.rating ? (
      <div
        aria-label={`Rated ${testimonial.rating} out of 5`}
        className="mt-3 flex items-center gap-0.5"
      >
        {Array.from({ length: STAR_COUNT }, (_, position) => {
          const filled = position < Math.round(testimonial.rating ?? 0);
          return (
            <Star
              aria-hidden="true"
              className={cn(
                "size-3.5",
                // Neutral: the one accent in this component is the open
                // trigger's underline, and a row of pink stars would outrank it.
                filled
                  ? "fill-foreground/75 text-foreground/75"
                  : "fill-transparent text-foreground/20"
              )}
              key={`${cardId}-star-${position}`}
            />
          );
        })}
      </div>
    ) : null}
  </div>
);

const InlineTestimonials = ({
  text,
  testimonials,
  avatarSize = DEFAULT_AVATAR_SIZE,
  openId,
  onOpenChange,
  className,
}: InlineTestimonialsProps) => {
  const prefersReducedMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const shouldReduceMotion = prefersReducedMotion || !motionOn;
  const isHoverDevice = useHoverCapable();
  const [internalOpenId, setInternalOpenId] = useState<string | null>(null);
  const [position, setPosition] = useState<CardPosition | null>(null);
  const [cardHeight, setCardHeight] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement | null>(null);
  const triggerRefs = useRef(new Map<string, HTMLButtonElement>());
  const closeTimerRef = useRef<number | null>(null);

  const isControlled = openId !== undefined;
  const activeOpenId = isControlled ? openId : internalOpenId;

  const clearCloseTimer = useCallback(() => {
    if (closeTimerRef.current !== null) {
      window.clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, []);

  useEffect(() => clearCloseTimer, [clearCloseTimer]);

  const commitOpenId = useCallback(
    (id: string | null) => {
      if (!isControlled) {
        setInternalOpenId(id);
      }
      onOpenChange?.(id);
    },
    [isControlled, onOpenChange]
  );

  const open = useCallback(
    (id: string) => {
      clearCloseTimer();
      commitOpenId(id);
    },
    [clearCloseTimer, commitOpenId]
  );

  const close = useCallback(() => {
    clearCloseTimer();
    commitOpenId(null);
  }, [clearCloseTimer, commitOpenId]);

  // A delayed close keeps the card alive while the pointer crosses the gap
  // between the trigger and the card — the usual source of popover flicker.
  const scheduleClose = useCallback(() => {
    clearCloseTimer();
    closeTimerRef.current = window.setTimeout(() => {
      commitOpenId(null);
    }, CLOSE_DELAY_MS);
  }, [clearCloseTimer, commitOpenId]);

  const measure = useCallback((id: string) => {
    const container = containerRef.current;
    const trigger = triggerRefs.current.get(id);
    if (!(container && trigger)) {
      return;
    }
    const containerRect = container.getBoundingClientRect();
    const triggerRect = trigger.getBoundingClientRect();
    const width = Math.min(
      CARD_WIDTH_PX,
      Math.max(containerRect.width - EDGE_PADDING_PX * 2, 0)
    );
    const center =
      triggerRect.left - containerRect.left + triggerRect.width / 2;
    const maxLeft = Math.max(
      containerRect.width - width - EDGE_PADDING_PX,
      EDGE_PADDING_PX
    );
    const left = Math.min(
      Math.max(center - width / 2, EDGE_PADDING_PX),
      maxLeft
    );
    setPosition({
      left,
      originX: center - left,
      // Vertical room is measured against the viewport, not the paragraph:
      // the paragraph is only a few lines tall, so the card would always
      // "not fit" and never get the chance to sit below its trigger.
      spaceAbove: triggerRect.top,
      spaceBelow: window.innerHeight - triggerRect.bottom,
      triggerBottom: triggerRect.bottom - containerRect.top,
      triggerTop: triggerRect.top - containerRect.top,
      width,
    });
  }, []);

  // Clamping happens against live measurements, so the card can never
  // overflow the container sideways — and it follows the trigger on
  // resize and scroll.
  useEffect(() => {
    if (!activeOpenId) {
      return;
    }
    measure(activeOpenId);
    const remeasure = () => measure(activeOpenId);
    window.addEventListener("resize", remeasure);
    window.addEventListener("scroll", remeasure, true);
    return () => {
      window.removeEventListener("resize", remeasure);
      window.removeEventListener("scroll", remeasure, true);
    };
  }, [activeOpenId, measure]);

  // The rendered popover's own height decides whether it still fits below.
  // This measures the gap-plus-card wrapper, not the card alone.
  useEffect(() => {
    const node = cardRef.current;
    if (node) {
      const next = node.offsetHeight;
      queueMicrotask(() => setCardHeight(next));
    }
  }, [activeOpenId, position]);

  useEffect(() => {
    if (!activeOpenId) {
      return;
    }
    const handleKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape") {
        return;
      }
      const trigger = triggerRefs.current.get(activeOpenId);
      close();
      trigger?.focus();
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [activeOpenId, close]);

  const handleContainerBlur = (event: FocusEvent<HTMLDivElement>) => {
    const next = event.relatedTarget as Node | null;
    if (next && containerRef.current?.contains(next)) {
      return;
    }
    close();
  };

  const handleTriggerFocus = (
    event: FocusEvent<HTMLButtonElement>,
    id: string
  ) => {
    // Only keyboard focus opens the card; a mouse click is handled by onClick,
    // otherwise focus-then-click would open and immediately close it again.
    if (event.currentTarget.matches(":focus-visible")) {
      open(id);
    }
  };

  const testimonialsById = new Map(
    testimonials.map((entry) => [entry.id, entry])
  );
  const segments = parseSegments(text);
  const activeTestimonial = activeOpenId
    ? testimonialsById.get(activeOpenId)
    : undefined;

  // Flip above the trigger when the card would spill past the viewport.
  const requiredSpace = cardHeight + EDGE_PADDING_PX;
  const flipUp = Boolean(
    position &&
      cardHeight > 0 &&
      position.spaceBelow < requiredSpace &&
      position.spaceAbove >= requiredSpace
  );
  // Enter and exit travel in the same direction, so opening and closing read
  // as one movement rather than two unrelated ones.
  const enterOffset = flipUp ? ENTER_OFFSET_PX : -ENTER_OFFSET_PX;

  return (
    <div
      className={cn("relative text-foreground/90 leading-relaxed", className)}
      data-reduced={prefersReducedMotion ? "true" : "false"}
      data-slot="inline-testimonials"
      onBlur={handleContainerBlur}
      ref={(node) => {
        containerRef.current = node;
        hostRef.current = node;
      }}
    >
      <p>
        {segments.map((segment, index) => {
          if (segment.type === "text") {
            return (
              <Fragment key={`text-${index}-${segment.value.slice(0, 8)}`}>
                {segment.value}
              </Fragment>
            );
          }

          const testimonial = testimonialsById.get(segment.id);
          if (!testimonial) {
            return null;
          }

          const isOpen = activeOpenId === testimonial.id;
          const cardId = `inline-testimonial-${testimonial.id}`;

          return (
            <button
              aria-controls={cardId}
              aria-expanded={isOpen}
              // An enriched word, not a chip: the name keeps the prose's size
              // and colour, and only picks up a face and a hairline rule under
              // it. Nothing here breaks the line's rhythm.
              className={cn(
                "group mx-[0.12em] inline-flex cursor-pointer items-center gap-[0.32em] rounded-[0.3em] align-middle font-medium text-foreground outline-none",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
              )}
              key={segment.id}
              onClick={() => (isOpen ? close() : open(testimonial.id))}
              onFocus={(event) => handleTriggerFocus(event, testimonial.id)}
              onMouseEnter={() => {
                if (isHoverDevice) {
                  open(testimonial.id);
                }
              }}
              onMouseLeave={() => {
                if (isHoverDevice) {
                  scheduleClose();
                }
              }}
              ref={(node) => {
                if (node) {
                  triggerRefs.current.set(testimonial.id, node);
                } else {
                  triggerRefs.current.delete(testimonial.id);
                }
              }}
              type="button"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
                alt=""
                className={cn(
                  "shrink-0 rounded-full object-cover ring-1 transition-[box-shadow] duration-150 ease-out",
                  isOpen ? "ring-brand/60" : "ring-foreground/15"
                )}
                height={avatarSize}
                src={testimonial.avatar}
                width={avatarSize}
              />
              <span
                className={cn(
                  // leading-none keeps the rule tight under the name: without
                  // it the span inherits the paragraph's line-height and the
                  // underline drops to the bottom of the whole line box.
                  "border-b-[1.5px] pb-[0.08em] leading-none transition-colors duration-150 ease-out",
                  isOpen
                    ? "border-brand"
                    : "border-foreground/25 group-hover:border-foreground/50"
                )}
              >
                {testimonial.name}
              </span>
            </button>
          );
        })}
      </p>
      <AnimatePresence>
        {activeTestimonial && position ? (
          // AnimatePresence drives exits through motion children of its own, so
          // the positioned wrapper IS the animated element. Its padding is the
          // gap AND a hover bridge: it keeps the pointer inside the card's
          // hover region on its way over from the trigger.
          <motion.div
            animate={{ opacity: 1, scale: 1, y: 0 }}
            className={cn("absolute z-20", flipUp ? "pb-2" : "pt-2")}
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: INSTANT }
                : {
                    opacity: 0,
                    scale: 0.97,
                    transition: EXIT_TRANSITION,
                    y: enterOffset,
                  }
            }
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { opacity: 0, scale: 0.97, y: enterOffset }
            }
            key="inline-testimonial-popover"
            onMouseEnter={clearCloseTimer}
            onMouseLeave={scheduleClose}
            ref={cardRef}
            style={{
              left: position.left,
              top: flipUp
                ? position.triggerTop - cardHeight
                : position.triggerBottom,
              // Scale from the trigger's centre, at the card's own edge rather
              // than the bridge padding's.
              transformOrigin: `${position.originX}px ${
                flipUp ? `${cardHeight - CARD_GAP_PX}px` : `${CARD_GAP_PX}px`
              }`,
              width: position.width,
            }}
            transition={shouldReduceMotion ? INSTANT : SPRING}
          >
            <QuoteCard
              avatarSize={avatarSize}
              cardId={`inline-testimonial-${activeTestimonial.id}`}
              testimonial={activeTestimonial}
            />
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
};

export { InlineTestimonials };

import * as React from "react"

import { ArrowRight } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

export type InteractiveHoverButtonProps = React.ComponentProps<typeof Button> & {
  /** 滑出时长，毫秒。不传或 300 仍是 duration-300。 */
  duration?: number
  /** 滑出距离倍率。不传或 1 仍是 12px 与 24px。 */
  scale?: number
}

function InteractiveHoverButton({
  className,
  children,
  duration,
  scale,
  variant,
  size,
  asChild = false,
  ...props
}: InteractiveHoverButtonProps) {
  const slotted =
    asChild && React.isValidElement<{ children?: React.ReactNode }>(children) ? children : null
  const timed = duration === undefined || duration === 300
  const ms = timed ? 300 : duration
  const shift = scale === undefined || scale === 1 ? undefined : 12 * scale
  const canonical = timed && shift === undefined
  const content = (
    <>
      <span
        className={
          canonical
            ? "inline-flex items-center gap-2 transition-transform duration-300 group-hover:-translate-x-3 motion-reduce:transition-none motion-reduce:group-hover:translate-x-0"
            : cn(
                "inline-flex items-center gap-2 transition-transform motion-reduce:transition-none motion-reduce:group-hover:translate-x-0",
                shift === undefined ? "group-hover:-translate-x-3" : "group-hover:-translate-x-[var(--shift)]",
                timed && "duration-300",
              )
        }
        style={
          canonical
            ? undefined
            : ({
                ...(timed ? {} : { transitionDuration: `${ms}ms` }),
                ...(shift === undefined ? {} : { "--shift": `${shift}px` }),
              } as React.CSSProperties)
        }
      >
        {slotted ? slotted.props.children : children}
      </span>
      <span
        className={
          canonical
            ? "absolute right-4 size-4 translate-x-6 opacity-0 transition-all duration-300 group-hover:translate-x-0 group-hover:opacity-100 motion-reduce:translate-x-0"
            : cn(
                "absolute right-4 size-4 opacity-0 transition-all group-hover:translate-x-0 group-hover:opacity-100 motion-reduce:translate-x-0",
                shift === undefined ? "translate-x-6" : "translate-x-[var(--travel)]",
                timed && "duration-300",
              )
        }
        style={
          canonical
            ? undefined
            : ({
                ...(timed ? {} : { transitionDuration: `${ms}ms` }),
                ...(shift === undefined ? {} : { "--travel": `${shift * 2}px` }),
              } as React.CSSProperties)
        }
      >
        <ArrowRight className="size-4" />
      </span>
    </>
  )

  return (
    <Button
      data-slot="interactive-hover-button"
      variant={variant}
      size={size}
      asChild={asChild}
      className={cn(
        "group relative justify-start overflow-hidden rounded-full font-normal",
        variant == null && "border bg-background text-foreground hover:bg-background",
        size == null && "h-10 px-6",
        className,
      )}
      {...props}
    >
      {slotted ? React.cloneElement(slotted, {}, content) : content}
    </Button>
  )
}

export { InteractiveHoverButton }

"use client"

/* eslint-disable @next/next/no-img-element -- registry 组件不能依赖 next/image */

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/interactive-image-selector/index.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"

import { Share2, Trash2 } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { useCallback, useState } from "react";

const RESET_DELAY = 200;
const RESET_SCALE_START = 1;
const RESET_SCALE_PEAK = 1.1;
const RESET_SCALE_END = 1;
const RESET_ROTATE_START = 0;
const RESET_ROTATE_POSITIVE = 5;
const RESET_ROTATE_NEGATIVE = -5;
const SELECT_SCALE_START = 1;
const SELECT_SCALE_PEAK = 1.1;
const SELECT_SCALE_END = 1;
const SELECT_ROTATE_START = 0;
const SELECT_ROTATE_NEGATIVE = -5;
const SELECT_ROTATE_POSITIVE = 5;
const CONTAINER_SCALE_START = 1;
const CONTAINER_SCALE_MIN = 0.95;
const CONTAINER_SCALE_END = 1;
const ITEM_SCALE_START = 1;
const ITEM_SCALE_MIN = 0.9;
const ITEM_SCALE_END = 1;
const ITEM_ROTATE_START = 0;
const ITEM_ROTATE_POSITIVE = 2;
const ITEM_ROTATE_NEGATIVE = -2;
const RESET_ANIMATION_DURATION = 0.3;

export interface ImageData {
  id: number;
  src: string;
}

export interface InteractiveImageSelectorProps {
  className?: string;
  images: ImageData[];
  onChange?: (selected: number[]) => void;
  onDelete?: (deleted: number[]) => void;
  onShare?: (selected: number[]) => void;
  selectable?: boolean;
  selectedImages?: number[];
}

export function InteractiveImageSelector({
  images,
  selectedImages: controlledSelected,
  onChange,
  onDelete,
  onShare,
  className = "",
  selectable = false,
}: InteractiveImageSelectorProps) {
  const [originalImages] = useState<ImageData[]>(images);
  const [internalImages, setInternalImages] = useState<ImageData[]>(images);
  const [internalSelected, setInternalSelected] = useState<number[]>([]);
  const [isSelecting, setIsSelecting] = useState(selectable);
  const [isResetting, setIsResetting] = useState(false);
  const shouldReduceMotion = usePrefersReducedMotion();

  const selected = controlledSelected ?? internalSelected;

  const handleImageClick = useCallback(
    (id: number) => {
      if (!isSelecting) {
        return;
      }
      const newSelected = selected.includes(id)
        ? selected.filter((imgId) => imgId !== id)
        : [...selected, id];
      if (onChange) {
        onChange(newSelected);
      } else {
        setInternalSelected(newSelected);
      }
    },
    [isSelecting, selected, onChange]
  );

  const handleDelete = useCallback(() => {
    const newImages = internalImages.filter(
      (img) => !selected.includes(img.id)
    );
    if (onDelete) {
      onDelete(selected);
    }
    setInternalImages(newImages);
    if (onChange) {
      onChange([]);
    } else {
      setInternalSelected([]);
    }
  }, [selected, internalImages, onDelete, onChange]);

  const handleReset = useCallback(() => {
    setIsResetting(true);

    // Add a small delay to show the reset animation
    setTimeout(() => {
      setInternalImages(originalImages);
      if (onChange) {
        onChange([]);
      } else {
        setInternalSelected([]);
      }
      setIsSelecting(false);
      setIsResetting(false);
    }, RESET_DELAY);
  }, [originalImages, onChange]);

  const toggleSelecting = useCallback(() => {
    setIsSelecting((prev) => !prev);
    if (isSelecting) {
      if (onChange) {
        onChange([]);
      } else {
        setInternalSelected([]);
      }
    }
  }, [isSelecting, onChange]);

  const handleShare = useCallback(() => {
    if (onShare) {
      onShare(selected);
    }
  }, [onShare, selected]);

  return (
    <div
      className={`relative flex h-full w-full max-w-[500px] flex-col justify-between p-4 ${className}`}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="interactive-image-selector"
    >
      <div className="pointer-events-none absolute inset-x-0 top-0 z-10 h-28 bg-linear-to-b from-primary/80 to-transparent dark:from-background/50" />
      <div className="absolute top-5 right-5 left-5 z-20 flex justify-between p-4">
        <motion.button
          animate={
            shouldReduceMotion || !isResetting
              ? {}
              : {
                  rotate: [
                    RESET_ROTATE_START,
                    RESET_ROTATE_POSITIVE,
                    RESET_ROTATE_NEGATIVE,
                    RESET_ROTATE_START,
                  ],
                  scale: [RESET_SCALE_START, RESET_SCALE_PEAK, RESET_SCALE_END],
                }
          }
          aria-label="Reset selection"
          className={`cursor-pointer rounded-full px-3 py-1 font-semibold text-sm bg-blend-luminosity backdrop-blur-xl transition-colors ${
            isResetting
              ? "bg-brand/30 text-white"
              : "bg-background/20 text-foreground"
          }`}
          disabled={isResetting}
          exit={shouldReduceMotion ? {} : { rotate: 0 }}
          initial={shouldReduceMotion ? {} : { rotate: 0 }}
          onClick={handleReset}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.25 }}
          whileHover={shouldReduceMotion ? {} : { scale: 1.05 }}
          whileTap={shouldReduceMotion ? {} : { scale: 0.95 }}
        >
          {isResetting ? "Resetting..." : "Reset"}
        </motion.button>
        <motion.button
          animate={
            isSelecting
              ? {
                  rotate: [
                    SELECT_ROTATE_START,
                    SELECT_ROTATE_NEGATIVE,
                    SELECT_ROTATE_POSITIVE,
                    SELECT_ROTATE_START,
                  ],
                  scale: [
                    SELECT_SCALE_START,
                    SELECT_SCALE_PEAK,
                    SELECT_SCALE_END,
                  ],
                }
              : {}
          }
          aria-label={isSelecting ? "Cancel selection" : "Select images"}
          className={`cursor-pointer rounded-full px-3 py-1 font-semibold text-sm bg-blend-luminosity backdrop-blur-xl ${
            isSelecting
              ? "bg-brand/30 text-white"
              : "bg-background/20 text-foreground"
          }`}
          exit={{ rotate: 0 }}
          initial={{ rotate: 0 }}
          onClick={toggleSelecting}
          transition={{ duration: 0.3 }}
          type="button"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {isSelecting ? "Cancel" : "Select"}
        </motion.button>
      </div>

      <motion.div
        animate={
          shouldReduceMotion || !isResetting
            ? {}
            : {
                scale: [
                  CONTAINER_SCALE_START,
                  CONTAINER_SCALE_MIN,
                  CONTAINER_SCALE_END,
                ],
              }
        }
        className="grid grid-cols-3 gap-1 overflow-scroll"
        layout={!shouldReduceMotion}
        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.2 }}
      >
        <AnimatePresence>
          {internalImages.map((img) => (
            <motion.div
              animate={{
                opacity: 1,
                rotate: isResetting
                  ? [
                      ITEM_ROTATE_START,
                      ITEM_ROTATE_POSITIVE,
                      ITEM_ROTATE_NEGATIVE,
                      ITEM_ROTATE_START,
                    ]
                  : 0,
                scale: isResetting
                  ? [ITEM_SCALE_START, ITEM_SCALE_MIN, ITEM_SCALE_END]
                  : 1,
              }}
              className="relative aspect-square cursor-pointer"
              exit={{ opacity: 0, scale: 0.8 }}
              initial={{ opacity: 0, scale: 0.8 }}
              key={img.id}
              layout
              onClick={() => handleImageClick(img.id)}
              transition={{
                damping: 25,
                duration: isResetting ? RESET_ANIMATION_DURATION : undefined,
                stiffness: 300,
                type: "spring" as const,
              }}
            >
              <img
                alt={`Gallery item ${img.id}`}
                className={`h-full w-full rounded-lg object-cover ${
                  selected.includes(img.id) && isSelecting ? "opacity-75" : ""
                }`}
                draggable={false}
                height={200}
                loading="lazy"
                src={img.src}
                width={200}
              />
              {isSelecting && selected.includes(img.id) && (
                <div className="absolute right-2 bottom-2 flex h-6 w-6 items-center justify-center rounded-full border border-white bg-brand text-white">
                  ✓
                </div>
              )}
            </motion.div>
          ))}
        </AnimatePresence>
      </motion.div>
      <AnimatePresence>
        {isSelecting ? (
          <motion.div
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }}
            className="absolute right-2 bottom-0 left-1/2 z-10 flex w-2/3 -translate-x-1/2 items-center justify-between rounded-full bg-background/20 p-4 bg-blend-luminosity backdrop-blur-md"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { opacity: 0, y: 20 }
            }
            initial={
              shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 20 }
            }
            transition={
              shouldReduceMotion ? { duration: 0 } : { duration: 0.25 }
            }
          >
            <button
              className="cursor-pointer text-brand"
              onClick={handleShare}
              type="button"
            >
              <Share2 size={24} />
            </button>
            <span className="text-foreground">{selected.length} selected</span>
            <button
              className="cursor-pointer text-brand"
              disabled={selected.length === 0}
              onClick={handleDelete}
              type="button"
            >
              <Trash2 size={24} />
            </button>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface IntroPreloaderProps {
  className?: string
  children?: React.ReactNode
  interval?: number
  duration?: number
  delay?: number
  count?: number
  color?: string
}

const STORAGE_KEY = "effect-ui-intro-preloader"
const INTRO_EVENT = "effect-ui-intro"

function IntroPreloader({ className, children, interval, duration, delay, count, color }: IntroPreloaderProps) {
  const reduced = usePrefersReducedMotion()
  const tickMs = interval === undefined || interval === 32 ? 32 : interval
  const panels = count === undefined || count === 5 ? 5 : count
  const curtainMs = duration === undefined || duration === 700 ? 700 : duration
  const staggerMs = delay === undefined || delay === 70 ? 70 : delay
  const [progress, setProgress] = React.useState(0)
  const [phase, setPhase] = React.useState<"count" | "curtains" | "done">("count")
  const seen = React.useSyncExternalStore(
    (onChange) => {
      window.addEventListener(INTRO_EVENT, onChange)
      return () => window.removeEventListener(INTRO_EVENT, onChange)
    },
    () => window.sessionStorage.getItem(STORAGE_KEY) === "1",
    () => false,
  )

  React.useEffect(() => {
    if (reduced || seen) return
    let value = 0
    let timeout = 0
    const timer = window.setInterval(() => {
      value = Math.min(100, value + 4)
      setProgress(value)
      if (value >= 100) {
        window.clearInterval(timer)
        setPhase("curtains")
        timeout = window.setTimeout(() => {
          window.sessionStorage.setItem(STORAGE_KEY, "1")
          window.dispatchEvent(new Event(INTRO_EVENT))
          setPhase("done")
        }, 900)
      }
    }, tickMs)
    return () => {
      window.clearInterval(timer)
      window.clearTimeout(timeout)
    }
  }, [reduced, seen, tickMs])

  return (
    <div className={cn("relative min-h-80 overflow-hidden rounded-2xl border bg-zinc-950 text-white", className)}>
      <div className="grid min-h-80 place-items-center p-8">
        {children ?? <p className="font-display text-4xl">页面已经打开</p>}
      </div>
      {!reduced && !(seen && phase !== "curtains") ? (
        <div className="absolute inset-0 z-10">
          <div className="absolute inset-0 flex">
            {Array.from({ length: panels }, (_, index) => (
              <span
                key={index}
                className={color ? "h-full flex-1" : "h-full flex-1 bg-zinc-950"}
                style={{
                  transform: phase === "curtains" ? "translateY(-100%)" : "translateY(0)",
                  transition: reduced ? "none" : `transform ${curtainMs}ms ${index * staggerMs}ms ease`,
                  ...(color ? { backgroundColor: color } : null),
                }}
              />
            ))}
          </div>
          {phase === "count" ? (
            <div className="absolute inset-0 grid place-items-center">
              <p className="font-mono text-6xl tabular-nums">{String(progress).padStart(3, "0")}</p>
            </div>
          ) : null}
        </div>
      ) : (
        <button
          type="button"
          className="absolute right-3 bottom-3 rounded-full border border-white/20 px-3 py-1 text-xs"
          onClick={() => {
            window.sessionStorage.removeItem(STORAGE_KEY)
            window.dispatchEvent(new Event(INTRO_EVENT))
            setProgress(0)
            setPhase("count")
          }}
        >
          再播一次
        </button>
      )}
    </div>
  )
}

export { IntroPreloader }

