import { useId, useRef, useState, type FormEvent } from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface InvalidShakeProps {
  color?: string
  duration?: number
  intensity?: number
  label?: string
  placeholder?: string
  submitLabel?: string
  errorLabel?: string
  successLabel?: string
  className?: string
}

function cssName(id: string) {
  return `shake-${id.replace(/[^a-zA-Z0-9_-]/g, "")}`
}

function playShake(node: HTMLElement, animation: string, duration: number) {
  node.style.animation = "none"
  void node.offsetWidth
  node.style.animation = `${animation} ${Math.max(0, duration)}ms ease-in-out`
}

export function InvalidShake({
  color = "var(--destructive)",
  duration = 420,
  intensity = 8,
  label = "Email",
  placeholder = "name@example.com",
  submitLabel = "Submit",
  errorLabel = "Enter a valid email.",
  successLabel = "Address saved.",
  className,
}: InvalidShakeProps) {
  const rootRef = useRef<HTMLFormElement>(null)
  const fieldRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const live = useAnimationActive(rootRef)
  const reduced = usePrefersReducedMotion()
  const animation = cssName(useId())
  const [invalid, setInvalid] = useState(false)
  const [done, setDone] = useState(false)
  const distance = `${intensity}px`

  function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const value = inputRef.current?.value.trim() ?? ""
    const ok = value.includes("@") && value.includes(".")
    setDone(ok)
    setInvalid(!ok)
    const field = fieldRef.current
    if (!field) return
    if (!ok && live && !reduced) playShake(field, animation, duration)
    else field.style.animation = "none"
  }

  return (
    <form ref={rootRef} noValidate onSubmit={onSubmit} className={cn("flex w-full max-w-sm flex-col gap-3", className)}>
      <style>
        {`@keyframes ${animation} {
          20% { transform: translateX(calc(var(--shake) * -1)); }
          40% { transform: translateX(var(--shake)); }
          60% { transform: translateX(calc(var(--shake) * -0.6)); }
          80% { transform: translateX(calc(var(--shake) * 0.4)); }
          100% { transform: none; }
        }`}
      </style>
      <label className="text-sm font-medium text-foreground" htmlFor={`${animation}-email`}>
        {label}
      </label>
      <div
        ref={fieldRef}
        className="motion-reduce:[animation:none]"
        style={{ ["--shake" as string]: distance }}
      >
        <input
          ref={inputRef}
          id={`${animation}-email`}
          type="email"
          placeholder={placeholder}
          aria-invalid={invalid || undefined}
          className="w-full rounded-md border bg-background px-3 py-2 text-sm text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring"
          style={{ borderColor: invalid ? color : "var(--border)" }}
        />
      </div>
      <button type="submit" className="h-9 rounded-md bg-primary px-3 text-sm font-medium text-primary-foreground">
        {submitLabel}
      </button>
      <p role="status" className="min-h-5 text-sm" style={{ color: invalid ? color : "var(--muted-foreground)" }}>
        {invalid ? errorLabel : done ? successLabel : ""}
      </p>
    </form>
  )
}

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { cn } from "@/lib/utils"

export interface IridescenceProps {
  className?: string
  children?: React.ReactNode
  speed?: number
  scale?: number
  intensity?: number
  color?: string
}

const VERT = `
attribute vec2 a_pos;
void main(){ gl_Position = vec4(a_pos, 0.0, 1.0); }
`

const FRAG = `
precision mediump float;
uniform vec2 u_res;
uniform float u_time;
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform vec3 u_color;
float hash(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 83147.3); }
float vnoise(vec2 p){
  vec2 i = floor(p); vec2 f = fract(p);
  float a = hash(i); float b = hash(i+vec2(1,0));
  float c = hash(i+vec2(0,1)); float d = hash(i+vec2(1,1));
  vec2 u = f*f*(3.0-2.0*f);
  return mix(a,b,u.x) + (c-a)*u.y*(1.0-u.x) + (d-b)*u.x*u.y;
}
float fbm(vec2 p){
  float v = 0.0; float a = 0.5;
  for (int i = 0; i < 5; i++) { v += a * vnoise(p); p *= 2.03; a *= 0.5; }
  return v;
}
void main(){
  vec2 uv = gl_FragCoord.xy / u_res;
  uv.x *= u_res.x / max(u_res.y, 1.0);
  float n = fbm(uv * 3.2 * u_scale + vec2(u_time * 0.07 * u_speed, -u_time * 0.04 * u_speed));
  float m = fbm(uv * 1.6 * u_scale - vec2(u_time * 0.03 * u_speed, u_time * 0.05 * u_speed));
  vec3 a = vec3(0.15, 0.05, 0.35);
  vec3 b = 0.5 + 0.5 * cos(6.2831 * (n + vec3(0.0, 0.33, 0.67)));
  vec3 c = 0.5 + 0.5 * cos(6.2831 * (m + vec3(0.18, 0.52, 0.84)));
  gl_FragColor = vec4(mix(a, mix(b, c, 0.55), u_intensity) * u_color, 1.0);
}
`

function compile(gl: WebGLRenderingContext, type: number, src: string) {
  const shader = gl.createShader(type)
  if (!shader) return null
  gl.shaderSource(shader, src)
  gl.compileShader(shader)
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader)
    return null
  }
  return shader
}

function hexToRgb(hex: string, fallback: [number, number, number]): [number, number, number] {
  const raw = hex.trim().replace(/^#/, "")
  const digits = raw.length === 3 ? [...raw].map((char) => `${char}${char}`).join("") : raw
  if (!/^[0-9a-fA-F]{6}$/.test(digits)) return fallback
  const value = Number.parseInt(digits, 16)
  return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
}

function useReducedMotion() {
  return React.useSyncExternalStore(
    (onChange) => {
      const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
      mq.addEventListener("change", onChange)
      return () => mq.removeEventListener("change", onChange)
    },
    () => window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    () => false,
  )
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function Iridescence({
  className,
  children,
  speed = 1,
  scale = 1,
  intensity = 0.85,
  color,
}: IridescenceProps) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(hostRef)
  const reduced = useReducedMotion()
  const [fallback, setFallback] = React.useState(false)
  const live = React.useRef({ speed: playbackRate(speed), scale, intensity, color })

  React.useEffect(() => {
    live.current = { speed: playbackRate(speed), scale, intensity, color }
  }, [speed, scale, intensity, color])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || reduced || !active) return
    const gl = canvas.getContext("webgl", { alpha: false })
    if (!gl) {
      queueMicrotask(() => setFallback(true))
      return
    }
    const vs = compile(gl, gl.VERTEX_SHADER, VERT)
    const fs = compile(gl, gl.FRAGMENT_SHADER, FRAG)
    const program = gl.createProgram()
    if (!vs || !fs || !program) {
      queueMicrotask(() => setFallback(true))
      return
    }
    gl.attachShader(program, vs)
    gl.attachShader(program, fs)
    gl.linkProgram(program)
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      queueMicrotask(() => setFallback(true))
      return
    }
    const buf = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buf)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW)
    const loc = gl.getAttribLocation(program, "a_pos")
    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect()
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      canvas.width = Math.max(1, Math.floor(width * dpr))
      canvas.height = Math.max(1, Math.floor(height * dpr))
    }
    resize()
    let frame = 0
    let time = 0
    const tick = () => {
      const spec = live.current
      const tint = hexToRgb(spec.color ?? "", [1, 1, 1])
      time += 0.016
      gl.viewport(0, 0, canvas.width, canvas.height)
      gl.useProgram(program)
      gl.bindBuffer(gl.ARRAY_BUFFER, buf)
      gl.enableVertexAttribArray(loc)
      gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0)
      gl.uniform2f(gl.getUniformLocation(program, "u_res"), canvas.width, canvas.height)
      gl.uniform1f(gl.getUniformLocation(program, "u_time"), time)
      gl.uniform1f(gl.getUniformLocation(program, "u_speed"), spec.speed)
      gl.uniform1f(gl.getUniformLocation(program, "u_scale"), spec.scale)
      gl.uniform1f(gl.getUniformLocation(program, "u_intensity"), spec.intensity)
      gl.uniform3f(gl.getUniformLocation(program, "u_color"), tint[0], tint[1], tint[2])
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
      frame = window.requestAnimationFrame(tick)
    }
    frame = window.requestAnimationFrame(tick)
    window.addEventListener("resize", resize)
    return () => {
      window.cancelAnimationFrame(frame)
      window.removeEventListener("resize", resize)
    }
  }, [active, reduced])

  return (
    <div ref={hostRef} className={cn("relative min-h-52 overflow-hidden rounded-xl", className)}>
      {fallback || reduced ? (
        <div className="absolute inset-0 bg-[conic-gradient(from_120deg,#7c3aed,#22d3ee,#f472b6,#7c3aed)]" />
      ) : (
        <canvas ref={canvasRef} className="absolute inset-0 size-full" />
      )}
      {children ? <div className="relative z-10">{children}</div> : null}
    </div>
  )
}

export { Iridescence }

