import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface LegoPixelateProps {
  image?: string
  blockSize?: number
  trigger?: "hover" | "view"
  speed?: number
  className?: string
}

const VERT = `
attribute vec2 uv;
attribute vec3 position;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`

const FRAG = `
precision highp float;
uniform sampler2D u_map;
uniform float u_blocks;
varying vec2 vUv;
void main() {
  float blocks = max(u_blocks, 1.0);
  vec2 cell = floor(vUv * blocks);
  vec2 sampleUv = (cell + 0.5) / blocks;
  vec3 color = texture2D(u_map, sampleUv).rgb;
  vec2 local = fract(vUv * blocks) - 0.5;
  float stud = smoothstep(0.2, 0.08, length(local));
  float edge = smoothstep(0.5, 0.38, max(abs(local.x), abs(local.y)));
  color = color * mix(0.62, 1.0, edge) + stud * 0.22;
  gl_FragColor = vec4(color, 1.0);
}
`

function paintScene() {
  const canvas = document.createElement("canvas")
  canvas.width = 640
  canvas.height = 400
  const context = canvas.getContext("2d")
  if (!context) return canvas
  const sky = context.createLinearGradient(0, 0, 0, 400)
  sky.addColorStop(0, "#7dd3fc")
  sky.addColorStop(1, "#fde68a")
  context.fillStyle = sky
  context.fillRect(0, 0, 640, 400)
  context.fillStyle = "#166534"
  context.fillRect(0, 250, 640, 150)
  context.fillStyle = "#b45309"
  context.fillRect(250, 150, 140, 120)
  context.fillStyle = "#f8fafc"
  context.fillRect(270, 180, 36, 36)
  context.fillRect(334, 180, 36, 36)
  return canvas
}

function LegoPixelate({ image, blockSize = 12, trigger = "hover", speed, className }: LegoPixelateProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const targetRef = React.useRef(blockSize)
  const rate = speed === undefined || speed === 1 ? 1 : speed
  const rateRef = React.useRef(rate)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback
  const preview = image

  React.useEffect(() => {
    targetRef.current = blockSize
    rateRef.current = rate
  }, [blockSize, rate])

  React.useEffect(() => {
    if (trigger !== "view" || !showCanvas) return
    const node = hostRef.current
    if (!node) return
    const observer = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) targetRef.current = 140
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [showCanvas, trigger])

  React.useEffect(() => {
    if (!showCanvas) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: true, dpr: Math.min(window.devicePixelRatio || 1, 1.5) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 35 })
      camera.position.z = 2.2
      const scene = new ogl.Transform()
      const map = new ogl.Texture(gl, { image: paintScene() })
      if (image) {
        const picture = new Image()
        picture.onload = () => {
          map.image = picture
          map.needsUpdate = true
        }
        picture.src = image
      }
      const uniforms = { u_map: { value: map }, u_blocks: { value: blockSize } }
      const program = new ogl.Program(gl, { vertex: VERT, fragment: FRAG, uniforms })
      const mesh = new ogl.Mesh(gl, { geometry: new ogl.Plane(gl, { width: 2.4, height: 1.5 }), program })
      mesh.setParent(scene)
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect: Math.max(rect.width, 1) / Math.max(rect.height, 1) })
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const tick = () => {
        const follow = rateRef.current === 1 ? 0.08 : 0.08 * rateRef.current
        uniforms.u_blocks.value += (targetRef.current - uniforms.u_blocks.value) * follow
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) queueMicrotask(() => { if (!cancelled) setFallback(true) })
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [blockSize, image, showCanvas])

  return (
    <div
      ref={hostRef}
      data-slot="lego-pixelate"
      className={cn("relative h-72 overflow-hidden rounded-xl border bg-slate-950", className)}
      onPointerEnter={() => {
        if (trigger === "hover") targetRef.current = 140
      }}
      onPointerLeave={() => {
        if (trigger === "hover") targetRef.current = blockSize
      }}
    >
      {showCanvas ? <canvas ref={canvasRef} className="absolute inset-0 size-full" /> : preview ? <div aria-hidden className="size-full bg-cover bg-center" style={{ backgroundImage: `url(${JSON.stringify(preview)})` }} /> : <div className="absolute inset-6 rounded-lg bg-linear-to-b from-sky-300 to-amber-200" />}
    </div>
  )
}

export { LegoPixelate }

"use client"

/* eslint-disable @next/next/no-img-element -- registry 组件不能依赖 next/image */

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface LensZoomProps {
  /** 要放大的图片。缺省时用内置色块，不请求外链。 */
  src?: string
  zoom?: number
  lensSize?: number
  intensity?: number
  color?: string
  className?: string
}

interface LensPoint {
  x: number
  y: number
  w: number
  h: number
}

function Artwork({ src }: { src?: string }) {
  if (src) {
    return <img src={src} alt="" draggable={false} className="h-full w-full object-cover" />
  }
  return (
    <div className="relative h-full w-full bg-zinc-950">
      <div className="absolute inset-0 bg-[linear-gradient(135deg,#1e1b4b_0%,#0f766e_48%,#b45309_100%)]" />
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: [
            "radial-gradient(circle at 22% 32%, #fde68a 0 7%, transparent 8%)",
            "radial-gradient(circle at 68% 38%, #67e8f9 0 11%, transparent 12%)",
            "radial-gradient(circle at 42% 74%, #f9a8d4 0 9%, transparent 10%)",
            "repeating-linear-gradient(90deg, transparent 0 18px, rgba(255,255,255,0.16) 18px 19px)",
          ].join(", "),
        }}
      />
      <div className="absolute inset-5 rounded-2xl border border-white/50" />
      <div className="absolute top-1/2 right-6 left-6 h-px bg-white/70" />
      <p className="absolute bottom-5 left-6 font-display text-4xl tracking-tight text-white">01</p>
    </div>
  )
}

function pointFrom(target: HTMLDivElement, clientX: number, clientY: number): LensPoint {
  const rect = target.getBoundingClientRect()
  return {
    x: Math.min(rect.width, Math.max(0, clientX - rect.left)),
    y: Math.min(rect.height, Math.max(0, clientY - rect.top)),
    w: rect.width,
    h: rect.height,
  }
}

function LensZoom({ src, zoom = 2.3, lensSize = 148, intensity, color, className }: LensZoomProps) {
  const reduced = usePrefersReducedMotion()
  const [lens, setLens] = React.useState<LensPoint | null>(null)
  const zoomAmount = zoom * (intensity === undefined || intensity === 1 ? 1 : intensity)
  const border = color?.trim().toLowerCase()
  const keepBorder = !border || border === "#fff" || border === "#ffffff" || border === "white"

  const move = (target: HTMLDivElement, clientX: number, clientY: number) => {
    if (reduced) return
    setLens(pointFrom(target, clientX, clientY))
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (reduced) return
    const step = event.key.startsWith("Arrow") ? 14 : 0
    if (!step) return
    event.preventDefault()
    const rect = event.currentTarget.getBoundingClientRect()
    const current = lens ?? { x: rect.width / 2, y: rect.height / 2, w: rect.width, h: rect.height }
    const dx = event.key === "ArrowLeft" ? -step : event.key === "ArrowRight" ? step : 0
    const dy = event.key === "ArrowUp" ? -step : event.key === "ArrowDown" ? step : 0
    setLens({
      x: Math.min(rect.width, Math.max(0, current.x + dx)),
      y: Math.min(rect.height, Math.max(0, current.y + dy)),
      w: rect.width,
      h: rect.height,
    })
  }

  return (
    <div
      data-slot="lens-zoom"
      tabIndex={0}
      aria-label="图像放大镜。悬停或用方向键移动圆形镜片。"
      className={cn(
        "relative h-72 w-full overflow-hidden rounded-xl border outline-none focus-visible:ring-2 focus-visible:ring-primary",
        className,
      )}
      onPointerMove={(event) => move(event.currentTarget, event.clientX, event.clientY)}
      onPointerLeave={(event) => {
        if (event.currentTarget.contains(document.activeElement)) return
        setLens(null)
      }}
      onFocus={(event) => {
        if (reduced) return
        const rect = event.currentTarget.getBoundingClientRect()
        setLens({ x: rect.width / 2, y: rect.height / 2, w: rect.width, h: rect.height })
      }}
      onBlur={() => setLens(null)}
      onKeyDown={onKeyDown}
    >
      <Artwork src={src} />
      {lens && !reduced ? (
        <div
          className={cn(
            "pointer-events-none absolute z-10 rounded-full border-2 shadow-[0_12px_40px_rgba(0,0,0,0.35)]",
            keepBorder && "border-white",
          )}
          style={{
            width: lensSize,
            height: lensSize,
            left: lens.x - lensSize / 2,
            top: lens.y - lensSize / 2,
            borderColor: keepBorder ? undefined : color,
          }}
        >
          <div className="absolute inset-0 overflow-hidden rounded-full bg-zinc-950">
            <div
              className="absolute top-0 left-0"
              style={{
                width: lens.w,
                height: lens.h,
                transformOrigin: "top left",
                transform: `translate(${lensSize / 2 - lens.x * zoomAmount}px, ${lensSize / 2 - lens.y * zoomAmount}px) scale(${zoomAmount})`,
              }}
            >
              <Artwork src={src} />
            </div>
          </div>
        </div>
