};

const VERTEX_SHADER = `#version 300 es
in vec2 a;
void main(){ gl_Position = vec4(a, 0.0, 1.0); }`;

const FRAGMENT_SHADER = `#version 300 es
precision highp float;
out vec4 fragColor;
uniform vec2 uRes;
uniform float uTime;
uniform float uDistortion;
uniform float uVariant;
uniform vec2 uPointer;

float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p){
  float value = 0.0;
  float amplitude = 0.5;
  mat2 turn = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 4; i++){
    value += amplitude * noise(p);
    p = turn * p;
    amplitude *= 0.5;
  }
  return value;
}

void main(){
  vec2 uv = gl_FragCoord.xy / uRes;
  vec2 aspect = vec2(uRes.x / uRes.y, 1.0);
  vec2 p = (uv - 0.5) * aspect * 2.2;
  vec2 push = uPointer * 0.55;
  float warp = clamp(uDistortion, 0.0, 3.0);

  vec2 q = vec2(fbm(p + push), fbm(p + vec2(5.2, 1.3) - push));
  vec2 flow = p + warp * 3.2 * q;
  vec2 r = vec2(
    fbm(flow + vec2(1.7, 9.2) + uTime * 0.17),
    fbm(flow + vec2(8.3, 2.8) - uTime * 0.13)
  );

  vec2 base = p + warp * 2.8 * r;
  float eps = 0.006;
  float h = fbm(base);
  float hx = fbm(base + vec2(eps, 0.0));
  float hy = fbm(base + vec2(0.0, eps));
  vec3 n = normalize(vec3((h - hx) / eps * 0.05, (h - hy) / eps * 0.05, 1.0));

  vec3 view = normalize(vec3((uv - 0.5) * aspect, 1.0));
  vec3 refl = reflect(view, n);
  float f = clamp(refl.y * 0.5 + 0.5, 0.0, 1.0);
  float sideways = clamp(refl.x * 0.5 + 0.5, 0.0, 1.0);

  vec3 lo = vec3(0.04, 0.05, 0.07);
  vec3 hi = vec3(0.90, 0.94, 0.99);
  vec3 tint = vec3(0.58, 0.68, 0.85);

  if (uVariant > 0.5 && uVariant < 1.5) {
    lo = vec3(0.16, 0.10, 0.02);
    hi = vec3(1.00, 0.90, 0.62);
    tint = vec3(0.82, 0.58, 0.14);
  } else if (uVariant > 1.5 && uVariant < 2.5) {
    lo = vec3(0.06, 0.08, 0.10);
    hi = vec3(1.00, 1.00, 1.00);
    tint = vec3(0.50, 0.58, 0.68);
  } else if (uVariant > 2.5) {
    lo = vec3(0.05, 0.03, 0.14);
    hi = vec3(0.85, 0.92, 1.00);
    tint = vec3(0.35, 0.55, 0.90);
  }

  vec3 col = mix(lo, hi, smoothstep(0.04, 0.96, f));
  col = mix(col, tint, pow(sideways, 2.0) * 0.55);

  float spec = pow(max(dot(n, normalize(vec3(0.35, 0.75, 0.55))), 0.0), 42.0);
  float fresnel = pow(1.0 - clamp(n.z, 0.0, 1.0), 3.0);
  col += spec * 0.85 + fresnel * 0.20;

  if (uVariant > 2.5) {
    vec3 sheen = 0.5 + 0.5 * cos(6.28318 * (f + h * 0.75 + vec3(0.0, 0.33, 0.67)));
    col = mix(col, sheen, 0.72);
  }

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}`;

const STRIP = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

interface MetalController {
  destroy: () => void;
  setDistortion: (value: number) => void;
  setPointer: (x: number, y: number) => void;
  setRunning: (running: boolean) => void;
  setSpeed: (value: number) => void;
  setVariant: (value: LiquidMetalVariant) => void;
}

const resizeCanvas = (canvas: HTMLCanvasElement, renderer: Renderer) => {
  const rect = (canvas.parentElement ?? canvas).getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
  renderer.dpr = dpr;
  renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1));
};

const createMetalController = (
  canvas: HTMLCanvasElement,
  initialVariant: LiquidMetalVariant,
  initialSpeed: number,
  initialDistortion: number
): MetalController | null => {
  const support = document.createElement("canvas").getContext("webgl2");
  if (!support) {
    return null;
  }
  let renderer: Renderer;
  try {
    renderer = new Renderer({
      canvas,
      webgl: 2,
      alpha: false,
      antialias: false,
      depth: false,
      powerPreference: "low-power",
      dpr: 1,
      autoClear: true,
    });
  } catch {
    return null;
  }
  const gl = renderer.gl;
  if (!gl || !renderer.isWebgl2) {
    gl?.getExtension("WEBGL_lose_context")?.loseContext();
    return null;
  }

  const uniforms = {
    uRes: { value: [1, 1] },
    uTime: { value: 0 },
    uDistortion: { value: initialDistortion },
    uVariant: { value: VARIANT_INDEX[initialVariant] },
    uPointer: { value: [0, 0] },
  };
  const program = new Program(gl, {
    vertex: VERTEX_SHADER,
    fragment: FRAGMENT_SHADER,
    uniforms,
    depthTest: false,
    depthWrite: false,
  });
  if (!gl.getProgramParameter(program.program, gl.LINK_STATUS)) {
    gl.getExtension("WEBGL_lose_context")?.loseContext();
    return null;
  }
  const geometry = new Geometry(gl, {
    a: { size: 2, data: STRIP },
    index: { data: new Uint16Array([0, 1, 2, 2, 1, 3]) },
  });
  const mesh = new Mesh(gl, { geometry, program, frustumCulled: false });
  const scene = new Transform();
  mesh.setParent(scene);
  const camera = new Camera(gl);
  camera.position.z = 1;

  let variant = initialVariant;
  let speed = initialSpeed;
  let distortion = initialDistortion;
  let elapsed = 0;
  let lastFrameAt = performance.now();
  let frame = 0;
  let running = false;
  let destroyed = false;
  let pointerX = 0;
  let pointerY = 0;
  let targetX = 0;
  let targetY = 0;

  const draw = () => {
    resizeCanvas(canvas, renderer);
    gl.clearColor(0, 0, 0, 1);
    uniforms.uRes.value = [canvas.width, canvas.height];
    uniforms.uTime.value = elapsed;
    uniforms.uDistortion.value = distortion;
    uniforms.uVariant.value = VARIANT_INDEX[variant];
    uniforms.uPointer.value = [pointerX, pointerY];
    renderer.render({ scene, camera, frustumCull: false });
  };

  const tick = () => {
    if (destroyed || !running) {
      return;
    }
    const now = performance.now();
    const delta = Math.min((now - lastFrameAt) / MS_PER_SECOND, MAX_FRAME_DELTA);
    lastFrameAt = now;
    elapsed += delta * speed;
    pointerX += (targetX - pointerX) * POINTER_EASE;
    pointerY += (targetY - pointerY) * POINTER_EASE;
    draw();
    frame = requestAnimationFrame(tick);
  };

  draw();

  return {
    destroy: () => {
      destroyed = true;
      running = false;
      cancelAnimationFrame(frame);
    },
    setDistortion: (value: number) => {
      distortion = value;
    },
    setPointer: (x: number, y: number) => {
      targetX = x;
      targetY = y;
    },
    setRunning: (next: boolean) => {
      if (destroyed || next === running) {
        return;
      }
      running = next;
      if (running) {
        lastFrameAt = performance.now();
        frame = requestAnimationFrame(tick);
        return;
      }
      cancelAnimationFrame(frame);
      draw();
    },
    setSpeed: (value: number) => {
      speed = value;
    },
    setVariant: (value: LiquidMetalVariant) => {
      variant = value;
    },
  };
};


const LiquidMetal = ({
  children,
  className,
  distortion = DEFAULT_DISTORTION,
  maskText = false,
  paused = false,
  pointerInfluence = true,
  speed = DEFAULT_SPEED,
  variant = "chrome",
}: LiquidMetalProps) => {
  const shouldReduceMotion = usePrefersReducedMotion();
  const wrapperRef = useRef<HTMLElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const controllerRef = useRef<MetalController | null>(null);
  const pointerRef = useRef({ x: 0, y: 0 });
  const [isSupported, setIsSupported] = useState(true);
  const motionOn = useAnimationActive(wrapperRef);

  const usesShader = !(maskText || shouldReduceMotion) && isSupported;
  const isPlaying = !(paused || shouldReduceMotion) && motionOn;

  // The GL context is rebuilt only when the rendering strategy changes; live
  // uniform values are pushed through the setters in the effect below.
  // biome-ignore lint/correctness/useExhaustiveDependencies: initial uniform values must not restart the context.
  useEffect(() => {
    if (!usesShader) {
      return;
    }
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const controller = createMetalController(
      canvas,
      variant,
      speed,
      distortion
    );
    if (!controller) {
      setIsSupported(false);
      return;
    }
    controllerRef.current = controller;
    return () => {
      controller.destroy();
      controllerRef.current = null;
    };
    // live uniforms go through the setters below
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [usesShader]);

  useEffect(() => {
    const controller = controllerRef.current;
    if (!controller) {
      return;
    }
    controller.setVariant(variant);
    controller.setSpeed(speed);
    controller.setDistortion(distortion);
  }, [distortion, speed, variant]);

  useEffect(() => {
    controllerRef.current?.setRunning(isPlaying);
  }, [isPlaying]);

  useEffect(() => {
    const wrapper = wrapperRef.current;
    if (!(wrapper && pointerInfluence) || shouldReduceMotion) {
      return;
    }
    const hoverQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    if (!hoverQuery.matches) {
      return;
    }

    const handleMove = (event: PointerEvent) => {
      const rect = wrapper.getBoundingClientRect();
      const x =
        ((event.clientX - rect.left) / rect.width - POINTER_CENTER) *
        POINTER_RANGE;
      const y =
        (POINTER_CENTER - (event.clientY - rect.top) / rect.height) *
        POINTER_RANGE;
      pointerRef.current = { x, y };
      controllerRef.current?.setPointer(x, y);
    };
    const handleLeave = () => {
      pointerRef.current = { x: 0, y: 0 };
      controllerRef.current?.setPointer(0, 0);
    };

    wrapper.addEventListener("pointermove", handleMove);
    wrapper.addEventListener("pointerleave", handleLeave);
    return () => {
      wrapper.removeEventListener("pointermove", handleMove);
      wrapper.removeEventListener("pointerleave", handleLeave);
    };
  }, [pointerInfluence, shouldReduceMotion]);

  useEffect(() => {
    const node = textRef.current;
    if (!(maskText && node) || shouldReduceMotion || paused || !motionOn) {
      return;
    }
    let frame = 0;
    const startedAt = performance.now();
    const step = () => {
      const seconds =
        ((performance.now() - startedAt) / MS_PER_SECOND) * Math.max(speed, 0);
      const cycle = (seconds / TEXT_SWEEP_SECONDS) % 1;
      const offset = pointerInfluence
        ? pointerRef.current.x * TEXT_POINTER_SHIFT
        : 0;
      node.style.backgroundPosition = `${cycle * TEXT_SWEEP_RANGE + offset}% 50%`;
      frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [motionOn, maskText, paused, pointerInfluence, shouldReduceMotion, speed]);

  if (maskText) {
    const textStyle: CSSProperties = {
      backgroundClip: "text",
      backgroundImage: TEXT_SURFACE[variant],
      backgroundPosition: `${TEXT_SWEEP_RANGE * HALF}% 50%`,
      backgroundSize: TEXT_BACKGROUND_SIZE,
      color: "transparent",
      WebkitBackgroundClip: "text",
      WebkitTextFillColor: "transparent",
    };

    return (
      <span
        className={cn("inline-block", className)}
        data-reduced={shouldReduceMotion ? "true" : "false"}
        data-slot="liquid-metal"
        ref={(node) => {
          wrapperRef.current = node;
        }}
      >
        <span ref={textRef} style={textStyle}>
          {children}
        </span>
      </span>
    );
  }

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-2xl bg-background",
        className
      )}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="liquid-metal"
      ref={(node) => {
        wrapperRef.current = node;
      }}
    >
      {usesShader ? (
        <div aria-hidden="true" className="absolute inset-0 z-0">
          <canvas className="h-full w-full" ref={canvasRef} />
        </div>
      ) : (
        <div
          aria-hidden="true"
          className="absolute inset-0 z-0"
          style={{ backgroundImage: FALLBACK_SURFACE[variant] }}
        />
      )}
      <div className="relative z-10">{children}</div>
    </div>
  );
};

export { LiquidMetal }

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface LiquidMorphSlideshowProps {
  images?: string[]
  interval?: number
  intensity?: number
  speed?: number
  className?: string
}

const FRAMES = [
  { label: "晨雾", from: "#fb7185", to: "#f59e0b" },
  { label: "海湾", from: "#38bdf8", to: "#1e3a8a" },
  { label: "林地", from: "#86efac", to: "#14532d" },
] as const

function paintFrame(label: string, from: string, to: string) {
  const canvas = document.createElement("canvas")
  canvas.width = 640
  canvas.height = 400
  const context = canvas.getContext("2d")
  if (!context) return canvas
  const gradient = context.createLinearGradient(0, 0, 640, 400)
  gradient.addColorStop(0, from)
  gradient.addColorStop(1, to)
  context.fillStyle = gradient
  context.fillRect(0, 0, 640, 400)
  context.fillStyle = "rgba(15,23,42,0.28)"
  context.fillRect(36, 250, 280, 72)
  context.fillStyle = "#f8fafc"
  context.font = "48px sans-serif"
  context.fillText(label, 56, 300)
  return canvas
}

function LiquidMorphSlideshow({ images, interval = 3200, intensity = 0.45, speed, className }: LiquidMorphSlideshowProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const indexRef = React.useRef(0)
  const intensityRef = React.useRef(intensity)
  const rate = speed === undefined || speed === 1 ? 1 : speed
  const rateRef = React.useRef(rate)
  const count = images?.length ? images.length : FRAMES.length
  const [caption, setCaption] = React.useState(0)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback

  React.useEffect(() => {
    intensityRef.current = intensity
    rateRef.current = rate
  }, [intensity, rate])

  React.useEffect(() => {
    const timer = window.setInterval(() => {
      indexRef.current = (indexRef.current + 1) % count
    }, Math.max(800, interval))
    return () => window.clearInterval(timer)
  }, [count, interval])

  React.useEffect(() => {
    if (!showCanvas) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    let running = true
    const visibleRef = { current: true }
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: false, dpr: Math.min(window.devicePixelRatio || 1, 1.5) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 35 })
      camera.position.z = 2.2
      const scene = new ogl.Transform()
      const textures = (images?.length ? images : FRAMES.map((item) => item)).map((source, index) => {
        const painted = FRAMES[index % FRAMES.length] ?? FRAMES[0]
        const texture = new ogl.Texture(gl, {
          image: paintFrame(painted.label, painted.from, painted.to),
          minFilter: gl.LINEAR,
          magFilter: gl.LINEAR,
          wrapS: gl.CLAMP_TO_EDGE,
          wrapT: gl.CLAMP_TO_EDGE,
        })
        if (typeof source === "string") {
          const picture = new Image()
          picture.onload = () => {
            texture.image = picture
            texture.needsUpdate = true
          }
          picture.src = source
        }
        return texture
      })
      const uniforms = {
        u_from: { value: textures[0] },
        u_to: { value: textures[1 % textures.length] },
        u_mix: { value: 0 },
        u_time: { value: 0 },
        u_intensity: { value: intensityRef.current },
      }
      const program = new ogl.Program(gl, {
        vertex: `
          attribute vec2 uv;
          attribute vec3 position;
          uniform mat4 modelViewMatrix;
          uniform mat4 projectionMatrix;
          varying vec2 vUv;
          void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `,
        fragment: `
          precision highp float;
          uniform sampler2D u_from;
          uniform sampler2D u_to;
          uniform float u_mix;
          uniform float u_time;
          uniform float u_intensity;
          varying vec2 vUv;
          void main() {
            float n = sin(vUv.x * 18.0 + u_time) * cos(vUv.y * 14.0 - u_time * 1.3);
            float n2 = sin((vUv.x + vUv.y) * 22.0 + u_time * 0.7);
            float wave = sin(u_mix * 3.14159);
            vec2 off = vec2(n, n2) * u_intensity * 0.18 * wave;
            vec4 fromColor = texture2D(u_from, vUv + off);
            vec4 toColor = texture2D(u_to, vUv - off);
            gl_FragColor = mix(fromColor, toColor, smoothstep(0.12, 0.88, u_mix));
          }
        `,
        uniforms,
      })
      const mesh = new ogl.Mesh(gl, { geometry: new ogl.Plane(gl, { width: 2.6, height: 1.6 }), program })
      mesh.setParent(scene)
      const resize = () => {
        const rect = host.getBoundingClientRect()
        const aspect = Math.max(rect.width, 1) / Math.max(rect.height, 1)
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect })
        const viewHeight = 2 * Math.tan((35 * Math.PI) / 360) * camera.position.z
        mesh.scale.set((viewHeight * aspect) / 2.6, viewHeight / 1.6, 1)
      }
      resize()
      const resizeObserver = new ResizeObserver(resize)
      resizeObserver.observe(host)
      let shown = 0
      let mix = 0
      let time = 0
      const tick = () => {
        if (!running) return
        if (!visibleRef.current) {
          frame = 0
          return
        }
        const rateNow = rateRef.current
        time += rateNow === 1 ? 0.016 : 0.016 * rateNow
        const target = indexRef.current % textures.length
        if (target !== shown) mix = Math.min(1, mix + 0.028 + intensityRef.current * 0.02)
        if (mix >= 1) {
          shown = (shown + 1) % textures.length
          mix = 0
          const nextCaption = shown
          queueMicrotask(() => {
            if (!cancelled) setCaption(nextCaption)
          })
        }
        uniforms.u_from.value = textures[shown]
        uniforms.u_to.value = textures[(shown + 1) % textures.length]
        uniforms.u_mix.value = target === shown ? 0 : mix
        uniforms.u_time.value = time
        uniforms.u_intensity.value = intensityRef.current
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      const viewObserver = new IntersectionObserver((entries) => {
        visibleRef.current = entries.some((entry) => entry.isIntersecting)
        if (visibleRef.current && running && frame === 0) frame = window.requestAnimationFrame(tick)
      })
      viewObserver.observe(host)
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        resizeObserver.disconnect()
        viewObserver.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) queueMicrotask(() => { if (!cancelled) setFallback(true) })
      return undefined
    })
    return () => {
      cancelled = true
      running = false
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [images, showCanvas])

  const slides = images?.length
    ? images.map((image, index) => ({ label: `画面 ${index + 1}`, image }))
    : FRAMES.map((frame) => ({ label: frame.label, from: frame.from, to: frame.to }))

  if (!showCanvas) {
    return (
      <div data-slot="liquid-morph-slideshow" className={cn("relative h-72 overflow-hidden rounded-xl border", className)}>
        {slides.map((slide, index) => (
          <div
            key={slide.label}
            className="absolute inset-0 transition-opacity duration-700"
            style={{
              opacity: index === caption % slides.length ? 1 : 0,
              backgroundImage: "image" in slide ? `url(${slide.image})` : `linear-gradient(135deg, ${slide.from}, ${slide.to})`,
              backgroundSize: "cover",
            }}
          />
        ))}
        <p className="absolute bottom-3 left-3 text-xs text-white">交叉淡入 {caption % slides.length + 1} / {slides.length}</p>
      </div>
    )
  }

  return (
    <div ref={hostRef} data-slot="liquid-morph-slideshow" className={cn("relative h-72 overflow-hidden rounded-xl border bg-slate-950", className)}>
      <canvas ref={canvasRef} className="absolute inset-0 size-full" aria-label="液体变形幻灯" />
      <p className="pointer-events-none absolute bottom-3 left-3 text-xs text-white/80">{(caption % count) + 1} / {count}</p>
    </div>
  )
}

export { LiquidMorphSlideshow }

