// Ported from Spell UI (MIT, (c) 2025 Spell UI) — https://github.com/xxtomm/spell-ui/blob/main/registry/spell-ui/logos-carousel.tsx

import { Children, useEffect, useId, useRef, useState, type ReactNode } from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface LogosCarouselProps {
  children?: ReactNode
  color?: string
  duration?: number
  interval?: number
  count?: number
  className?: string
}

function cssName(id: string, kind: "enter" | "exit") {
  return `logos-${kind}-${id.replace(/[^a-zA-Z0-9_-]/g, "")}`
}

export function LogosCarousel({
  children,
  color = "var(--foreground)",
  duration = 600,
  interval = 2500,
  count = 3,
  className,
}: LogosCarouselProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const live = useAnimationActive(rootRef)
  const reduced = usePrefersReducedMotion()
  const reactId = useId()
  const enter = cssName(reactId, "enter")
  const exit = cssName(reactId, "exit")
  const nodes = Children.toArray(children)
  const perGroup = Math.max(1, Math.round(count))
  const groups = Array.from({ length: Math.ceil(nodes.length / perGroup) }, (_, groupIndex) =>
    nodes.slice(groupIndex * perGroup, groupIndex * perGroup + perGroup),
  )
  const [index, setIndex] = useState(0)
  const safeIndex = groups.length === 0 ? 0 : (reduced ? 0 : index % groups.length)
  const moving = live && !reduced && groups.length > 1

  useEffect(() => {
    if (!moving) return
    const timer = window.setInterval(() => {
      setIndex((current) => (current + 1) % groups.length)
    }, Math.max(400, interval))
    return () => window.clearInterval(timer)
  }, [moving, interval, groups.length])

  if (groups.length === 0) {
    return <div className={cn("text-sm text-muted-foreground", className)}>No logos</div>
  }

  const next = (safeIndex + 1) % groups.length

  return (
    <div ref={rootRef} className={cn("grid w-full max-w-xl place-items-center", className)} aria-label="Logo carousel">
      <style>
        {`@keyframes ${enter} { from { transform: translateY(28px); filter: blur(4px); opacity: 0; } to { transform: none; filter: none; opacity: 1; } }
          @keyframes ${exit} { from { transform: none; filter: none; opacity: 1; } to { transform: translateY(-28px); filter: blur(4px); opacity: 0; } }`}
      </style>
      {groups.map((group, groupIndex) => {
        const current = groupIndex === safeIndex
        const incoming = moving && groupIndex === next
        if (!current && !incoming) return null
        return (
          <div key={groupIndex} className="flex w-full items-center justify-center gap-8" style={{ gridArea: "1 / 1" }}>
            {group.map((logo, logoIndex) => (
              <div
                key={logoIndex}
                className="text-lg font-semibold tracking-wide motion-reduce:animate-none"
                style={{
                  color,
                  animationName: moving ? (current ? exit : enter) : "none",
                  animationDuration: `${duration}ms`,
                  animationDelay: `${logoIndex * 0.12}s`,
                  animationFillMode: "both",
                  animationTimingFunction: "ease",
                  animationPlayState: moving ? "running" : "paused",
                }}
              >
                {logo}
              </div>
            ))}
          </div>
        )
      })}
    </div>
  )
}

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface LoomThreadsMarqueeProps {
  className?: string
  speed?: number
}

const VERT = `
attribute vec2 uv;
attribute vec3 position;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 1.0);
}
`

const FRAG = `
precision highp float;
uniform float u_time;
uniform float u_unravel;
varying vec2 vUv;

vec3 cardColor(float index) {
  float h = fract(index * 0.17);
  vec3 rgb = clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  return mix(vec3(0.16), rgb, 0.85);
}

void main() {
  float scroll = u_time * 0.12;
  float x = fract(vUv.x + scroll);
  float index = floor(x * 5.0);
  float local = fract(x * 5.0);
  float threadCount = mix(1.0, 28.0, u_unravel);
  float thread = fract((vUv.y + sin(index + u_time) * 0.02 * u_unravel) * threadCount);
  float solid = step(0.06, local) * step(local, 0.94);
  float line = smoothstep(0.5, 0.15, abs(thread - 0.5));
  float mask = mix(solid, line, u_unravel);
  float gap = mix(step(0.08, vUv.y) * step(vUv.y, 0.92), 1.0, u_unravel);
  vec3 color = cardColor(index) * mask * gap;
  gl_FragColor = vec4(color, 1.0);
}
`

function LoomFallback({ unravel }: { unravel: boolean }) {
  return (
    <div className="absolute inset-0 flex items-center gap-3 overflow-hidden bg-zinc-950 px-4">
      {Array.from({ length: 5 }, (_, index) => (
        <div
          key={index}
          className={unravel ? "h-24 w-1 rounded-full" : "h-28 w-24 rounded-lg"}
          style={{ background: `hsl(${index * 48 + 18} 70% 52%)` }}
        />
      ))}
    </div>
  )
}

function LoomThreadsMarquee({ className, speed }: LoomThreadsMarqueeProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const rate = speed === undefined || speed === 1 ? 1 : speed
  const rateRef = React.useRef(rate)
  const unravelRef = React.useRef(0)
  const [unravel, setUnravel] = React.useState(false)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback

  React.useEffect(() => {
    unravelRef.current = unravel ? 1 : 0
    rateRef.current = rate
  }, [rate, unravel])

  React.useEffect(() => {
    if (!showCanvas) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: false, dpr: Math.min(window.devicePixelRatio || 1, 1.5) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl)
      camera.position.z = 1
      const scene = new ogl.Transform()
      const geometry = new ogl.Plane(gl, { width: 2, height: 2 })
      const uniforms = { u_time: { value: 0 }, u_unravel: { value: 0 } }
      const program = new ogl.Program(gl, { vertex: VERT, fragment: FRAG, uniforms })
      const mesh = new ogl.Mesh(gl, { geometry, program })
      mesh.setParent(scene)
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const started = performance.now()
      let shown = 0
      const tick = () => {
        const rateNow = rateRef.current
        const lerp = rateNow === 1 ? 0.06 : 0.06 * rateNow
        shown += (unravelRef.current - shown) * lerp
        const elapsed = (performance.now() - started) / 1000
        uniforms.u_time.value = rateNow === 1 ? elapsed : elapsed * rateNow
        uniforms.u_unravel.value = shown
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
      }
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [showCanvas])

  return (
    <div data-slot="loom-threads-marquee" className={cn("w-full space-y-3", className)}>
      <button
        type="button"
        aria-pressed={unravel}
        className="rounded-md border px-3 py-1.5 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary"
        onClick={() => setUnravel((current) => !current)}
      >
        {unravel ? "织回画面" : "拆成丝线"}
      </button>
      <div ref={hostRef} className="relative h-64 overflow-hidden rounded-xl border bg-zinc-950">
        {showCanvas ? <canvas ref={canvasRef} className="absolute inset-0 size-full" /> : <LoomFallback unravel={unravel} />}
      </div>
    </div>
  )
}

export { LoomThreadsMarquee }

"use client"

import { motion, useMotionValue, useTransform } from "motion/react"
import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface MacbookScrollProps {
  className?: string
  intensity?: number
  scale?: number
  speed?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

function ScreenMock() {
  return (
    <div className="flex h-full flex-col bg-zinc-950 p-3 text-zinc-100">
      <div className="mb-3 h-2 w-16 rounded-full bg-white/30" />
      <div className="grid flex-1 grid-cols-[4rem_1fr] gap-2">
        <div className="space-y-2">
          <div className="h-8 rounded-md bg-cyan-400/70" />
          <div className="h-8 rounded-md bg-white/15" />
          <div className="h-8 rounded-md bg-white/15" />
        </div>
        <div className="rounded-md bg-[linear-gradient(160deg,#312e81,#0e7490_60%,#b45309)] p-3">
          <div className="h-2 w-1/2 rounded-full bg-white/70" />
          <div className="mt-6 h-16 rounded-md bg-white/20" />
        </div>
      </div>
    </div>
  )
}

function MacbookScroll({ className, intensity, scale: endScale, speed }: MacbookScrollProps) {
  const reduced = usePrefersReducedMotion()
  const progress = useMotionValue(reduced ? 1 : 0)
  const rate = pace(speed)
  const shaped = useTransform(progress, (value) =>
    rate === 1 ? value : Math.pow(Math.min(Math.max(value, 0), 1), rate),
  )
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const open = gain === 1 ? 68 : 68 * gain
  const end = endScale === undefined || endScale === 1 ? 1.7 : 1.7 * endScale
  const rotateX = useTransform(shaped, [0, 0.62], [-open, 0])
  const scale = useTransform(shaped, [0.4, 1], [1, end])

  const onScroll = (event: React.UIEvent<HTMLDivElement>) => {
    if (reduced) return
    const element = event.currentTarget
    const max = element.scrollHeight - element.clientHeight
    progress.set(max <= 0 ? 1 : element.scrollTop / max)
  }

  return (
    <div
      data-slot="macbook-scroll"
      tabIndex={0}
      aria-label="滚动时笔记本屏幕打开，画面再稍微放大。这是通用机身，没有品牌标志。"
      className={cn(
        "h-96 w-full overflow-auto rounded-xl border bg-zinc-950 outline-none focus-visible:ring-2 focus-visible:ring-primary",
        className,
      )}
      onScroll={onScroll}
    >
      <div className="h-[180vh]">
        <div className="sticky top-0 grid h-96 place-items-center [perspective:1100px]">
          <div className="w-72">
            <motion.div
              className="origin-bottom overflow-visible rounded-t-xl border border-b-0 border-white/20 bg-zinc-800 p-2"
              style={reduced ? { rotateX: 0 } : { rotateX }}
            >
              <motion.div className="h-40 overflow-hidden rounded-md" style={reduced ? undefined : { scale }}>
                <ScreenMock />
              </motion.div>
            </motion.div>
            <div className="h-3 rounded-b-xl bg-zinc-700 shadow-[0_16px_30px_rgba(0,0,0,0.35)]">
              <div className="mx-auto h-1 w-16 rounded-b-md bg-zinc-500" />
            </div>
            <p className="mt-4 text-center text-xs text-zinc-400">滚动展开屏幕</p>
          </div>
        </div>
      </div>
    </div>
  )
}

export { MacbookScroll }

